/*
 * FhostCmdExecute():
 *    The function is to execute FHOST command and return the generic response
 *    Note: only part of the generic response structure will be affected which corresponds the command executed
 */
dutCmdResponse_t *FhostCmdExecute(char *cmdStr, enum cmd_tags tag)
{
#ifdef CONFIG_RW_FHOST
    dutCmdResponse_t *fhostCmdResp = (dutCmdResponse_t *)malloc(sizeof(dutCmdResponse_t));
    // initialize the generic response
    memset(fhostCmdResp, 0, sizeof(dutCmdResponse_t));
    // file stream pointer to device file
    FILE *tmpfile = NULL;
    // temporary buffer used to read device file
    char strout[256];

    // open device file of rwnx_term for reading and writing
    tmpfile = fopen(term_dev, "r+");

    if(tmpfile == NULL)
    {
        DPRINT_ERR("Cannot open %s\r\n", term_dev);
        free(fhostCmdResp);
        return NULL;
    }

    // get the integer file descriptor associated with the file stream
    int fd = fileno(tmpfile);
    // get the file descriptor flags
    int flags = fcntl(fd, F_GETFL, 0);
    // add non-blocking flag
    flags |= O_NONBLOCK;
    // set the new flags for file descriptor
    fcntl(fd, F_SETFL, flags);

    // write the command string in the device file to execute it
    if (cmdStr != NULL)
    {
        fprintf(tmpfile, "%s", cmdStr);
        DPRINT_INFO("#-->CS FhostCmdExecute: The command string is %s\r\n",cmdStr);
    }
    // This may be the situation where we don't need the command but need to find the response from device file
    else
    {
        DPRINT_INFO("#-->CS FhostCmdExecute: The command string is NULL\r\n");
    }

    while (1)
    {
        fd_set fds;
        struct timeval tv;
        int retval;

        // wait up to 300ms to output data
        tv.tv_sec = 0;
        tv.tv_usec = 300000;
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        retval = select(fd + 1, &fds, NULL, NULL, &tv);

        // There's output data before timeout
        if(retval > 0)
        {
            // traverse the entire device file and try to get the latest trace
            while(fgets(strout, sizeof(strout) - 1, tmpfile))
            {
                switch(tag)
                {
                    case WFA_TRAFFIC_SEND_PING_TLV :
                        if (strncmp("Send ping ID ", strout, 13) == 0)
                        {
                            fhostCmdResp->streamId = atoi(strout + 13);
                            DPRINT_INFO("ping ID found : %d\r\n", fhostCmdResp->streamId);
                        }
                    break;

                    case WFA_TRAFFIC_STOP_PING_TLV :
                        // verify if it's the flag of ping stop command
                        if (strncmp("Stop ping ID : ", strout, 15) == 0)
                        {
                            int val;
                            char* hdr;

                            DPRINT_INFO("Stopped ping ID : %d\r\n", atoi(strout + 15));
                            // read output
                            fgets(strout, sizeof(strout) - 1, tmpfile);
                            // Skip ping header (--- <ip addr> ping statistics ---)
                            fgets(strout, sizeof(strout) - 1, tmpfile);
                            // read TX frames
                            val = atoi(strout);
                            hdr = strchr(strout, ' ');
                            if (strncmp(" packets transmitted, ", hdr, 22) == 0)
                            {
                                fhostCmdResp->cmdru.pingStp.sendCnt = val;
                                DPRINT_INFO("TX frames found : %d\r\n", fhostCmdResp->cmdru.pingStp.sendCnt);
                                strcpy(strout, hdr + strlen(" packets transmitted, "));
                            }
                            else
                            {
                                DPRINT_ERR("Error No TX frames\r\n");
                            }

                            // read RX frames
                            val = atoi(strout);
                            hdr = strchr(strout, ' ');
                            if (strncmp(" received", hdr, 9) == 0)
                            {
                                fhostCmdResp->cmdru.pingStp.repliedCnt = val;
                                DPRINT_INFO("RX frames found : %d\r\n", fhostCmdResp->cmdru.pingStp.repliedCnt);
                            }
                            else
                            {
                                DPRINT_ERR("Error No RX frames\r\n");
                            }
                        }
                    break;

                    case WFA_STA_IS_CONNECTED_TLV :
                        if (strncmp("fhost: [WPA] CTRL-EVENT-CONNECTED", strout, 33) == 0)
                        {
                            fhostCmdResp->cmdru.connected = 1;
                            DPRINT_INFO("fhost: [WPA] CTRL-EVENT-CONNECTED\r\n");
                        }
                        else if (strncmp("fhost: [WPA] CTRL-EVENT-NETWORK-NOT-FOUND", strout, 41) == 0)
                        {
                            fhostCmdResp->cmdru.connected = 0;
                            DPRINT_INFO("fhost: [WPA] CTRL-EVENT-NETWORK-NOT-FOUND\r\n");
                        }
                        else if (strncmp("fhost: [WPA] CTRL-EVENT-DISCONNECTED", strout, 36) == 0)
                        {
                            fhostCmdResp->cmdru.connected = 0;
                            DPRINT_INFO("fhost: [WPA] CTRL-EVENT-DISCONNECTED\r\n");
                        }
                    break;

                    case WFA_STA_GET_BSSID_TLV :
                        if (strncmp("fhost: [WPA] Associated with ", strout, 29) == 0)
                        {
                            // the length of BSSID is 17 bytes
                            strncpy(fhostCmdResp->cmdru.bssid, &(strout[29]), 17);
                            DPRINT_INFO("BSSID found : %s\r\n", fhostCmdResp->cmdru.bssid);
                        }
                    break;

                    case WFA_STA_GET_IP_CONFIG_TLV :
                        // [0] wl1: MAC=AA:07:CC:DD:EE:FF ip=192.168.241.73/24
                        if (strncmp("[0] wl1: ", strout, 9) == 0)
                        {
                            if (strncmp("ip=", strout + 31, 3) == 0)
                            {
                                // position of ip address
                                char *ip_p = strout + 34;
                                // position of mask
                                char *mask_p = strchr(strout, '/');

                                if (mask_p != NULL)
                                {
                                    int mask_num;
                                    int ip_len;
                                    ip_len = mask_p - ip_p;
                                    // retrieve ip address into response
                                    strncpy(fhostCmdResp->cmdru.getIfconfig.ipaddr, ip_p, ip_len);
                                    DPRINT_INFO("ipaddr : %s\r\n", fhostCmdResp->cmdru.getIfconfig.ipaddr);
                                    // convert mask bits format to dotted format
                                    mask_num = atoi(mask_p + 1);
                                    if (mask_num == 24)
                                    {
                                        strcpy(fhostCmdResp->cmdru.getIfconfig.mask, "255.255.255.0");
                                    }
                                    else if (mask_num == 16)
                                    {
                                        strcpy(fhostCmdResp->cmdru.getIfconfig.mask, "255.255.0.0");
                                    }
                                    else if (mask_num == 8)
                                    {
                                        strcpy(fhostCmdResp->cmdru.getIfconfig.mask, "255.0.0.0");
                                    }
                                    else
                                    {
                                        strcpy(fhostCmdResp->cmdru.getIfconfig.mask, "0.0.0.0");
                                    }
                                }
                                else
                                {
                                    DPRINT_ERR("Error IP address format\r\n");
                                }
                            }
                        }
                    break;

                    case WFA_STA_GET_MAC_ADDRESS_TLV:
                    // [0] wl1: MAC=AA:07:CC:DD:EE:FF ip=192.168.241.73/24
                    if (strncmp("[0] wl1: MAC=", strout, 13) == 0)
                    {
                        // position of MAC address
                        char *mac_p = strout + 13;

                        if (mac_p != NULL)
                        {
                            int mac_len = 17;
                            // retrieve MAC address into response
                            strncpy(fhostCmdResp->cmdru.mac, mac_p, mac_len);
                            DPRINT_INFO("MAC address : %s\r\n", fhostCmdResp->cmdru.mac);
                        }
                    }
                    break;

                    case WFA_TRAFFIC_AGENT_CONFIG_TLV :
                        // Successful configuration
                        if (strncmp("Configure stream ", strout, 17) == 0)
                        {
                            fhostCmdResp->streamId = atoi(strout + 17);
                            fhostCmdResp->status = STATUS_COMPLETE;
                            DPRINT_INFO("FhostCmdExecute : Configured stream %d\r\n", fhostCmdResp->streamId);
                        }
                        // Error of TG layer
                        else if (strncmp("Configuration error", strout, 19) == 0)
                        {
                            fhostCmdResp->streamId = -1;
                            fhostCmdResp->status = STATUS_ERROR;
                            DPRINT_INFO("FhostCmdExecute : Configuration error");
                        }
                        // Missing some parameters of TG command
                        else if (strncmp("No ", strout, 3) == 0)
                        {
                            fhostCmdResp->streamId = -1;
                            fhostCmdResp->status = STATUS_ERROR;
                            DPRINT_INFO("FhostCmdExecute : Missing parameters");
                        }
                    break;

                    case WFA_TRAFFIC_AGENT_SEND_TLV :
                        // FHOST TG start command
                        if (strncmp("Start stream id : ", strout, 18) == 0)
                        {
                            fhostCmdResp->streamId = atoi(strout + 18);
                            fhostCmdResp->status = STATUS_COMPLETE;
                            DPRINT_INFO("FhostCmdExecute : Started stream %d\r\n", fhostCmdResp->streamId);
                        }
                        else if (strncmp("No stream id", strout, 12) == 0)
                        {
                            fhostCmdResp->streamId = -1;
                            fhostCmdResp->status = STATUS_ERROR;
                            DPRINT_INFO("FhostCmdExecute : No stream id");
                        }
                        else if (strncmp("Can't start stream : ", strout, 21) == 0)
                        {
                            fhostCmdResp->streamId = atoi(strout + 21);
                            fhostCmdResp->status = STATUS_ERROR;
                            DPRINT_INFO("FhostCmdExecute : Can't start stream : %d\r\n", fhostCmdResp->streamId);
                        }
                        // FHOST TG stop command
                        else if (strncmp("STOP stream ID : ", strout, 17) == 0)
                        {
                            fhostCmdResp->streamId = atoi(strout + 17);
                            fhostCmdResp->status = STATUS_COMPLETE;
                             // read TX frames
                            fgets(strout, sizeof(strout) - 1, tmpfile);
                            if (strncmp("TX frames : ", strout, 12) == 0)
                            {
                                fhostCmdResp->cmdru.stats.txFrames = atoi(strout + 12);
                                DPRINT_INFO("TX frames found : %d\r\n", fhostCmdResp->cmdru.stats.txFrames);
                            }
                            else
                            {
                                DPRINT_ERR("Error No TX frames\r\n");
                            }

                            // read RX frames
                            fgets(strout, sizeof(strout) - 1, tmpfile);

                            if (strncmp("RX frames : ", strout, 12) == 0)
                            {
                                fhostCmdResp->cmdru.stats.rxFrames = atoi(strout + 12);
                                DPRINT_INFO("RX frames found : %d\r\n", fhostCmdResp->cmdru.stats.rxFrames);
                            }
                            else
                            {
                                DPRINT_ERR("Error No RX frames\r\n");
                            }

                             // read TX bytes
                            fgets(strout, sizeof(strout) - 1, tmpfile);
                            if (strncmp("TX bytes : ", strout, 11) == 0)
                            {
                                fhostCmdResp->cmdru.stats.txPayloadBytes = atoi(strout + 11);
                                DPRINT_INFO("TX bytes found : %llu\r\n", fhostCmdResp->cmdru.stats.txPayloadBytes);
                            }
                            else
                            {
                                DPRINT_ERR("Error No TX bytes\r\n");
                            }

                            // read RX bytes
                            fgets(strout, sizeof(strout) - 1, tmpfile);
                            if (strncmp("RX bytes : ", strout, 11) == 0)
                            {
                                fhostCmdResp->cmdru.stats.rxPayloadBytes = atoi(strout + 11);
                                DPRINT_INFO("RX bytes found : %llu\r\n", fhostCmdResp->cmdru.stats.rxPayloadBytes);
                            }
                            else
                            {
                                DPRINT_ERR("Error No RX bytes\r\n");
                            }

                            // we don't know the number of out of sequence frames from TG sending process, so set it 0
                            fhostCmdResp->cmdru.stats.outOfSequenceFrames = 0;
                        }
                        else if (strncmp("Can't stop stream : ", strout, 20) == 0)
                        {
                            fhostCmdResp->streamId = atoi(strout + 20);
                            fhostCmdResp->status = STATUS_ERROR;
                            DPRINT_INFO("FhostCmdExecute : Can't stop stream : %d\r\n", fhostCmdResp->streamId);
                        }
                    break;

                    case WFA_TRAFFIC_AGENT_RECV_START_TLV :
                        // FHOST TG start command
                        if (strncmp("Start stream id : ", strout, 18) == 0)
                        {
                            fhostCmdResp->streamId = atoi(strout + 18);
                            fhostCmdResp->status = STATUS_COMPLETE;
                            DPRINT_INFO("FhostCmdExecute : Started stream %d\r\n", fhostCmdResp->streamId);
                        }
                        else if (strncmp("No stream id", strout, 12) == 0)
                        {
                            fhostCmdResp->streamId = -1;
                            fhostCmdResp->status = STATUS_ERROR;
                            DPRINT_INFO("FhostCmdExecute : No stream id");
                        }
                        else if (strncmp("Can't start stream : ", strout, 21) == 0)
                        {
                            fhostCmdResp->streamId = atoi(strout + 21);
                            fhostCmdResp->status = STATUS_ERROR;
                            DPRINT_INFO("FhostCmdExecute : Can't start stream : %d\r\n", fhostCmdResp->streamId);
                        }
                    break;

                    case WFA_TRAFFIC_AGENT_RECV_STOP_TLV :
                        // FHOST TG stop command
                        if (strncmp("STOP stream ID : ", strout, 17) == 0)
                        {
                            fhostCmdResp->streamId = atoi(strout + 17);
                            fhostCmdResp->status = STATUS_COMPLETE;
                             // read TX frames
                            fgets(strout, sizeof(strout) - 1, tmpfile);
                            if (strncmp("TX frames : ", strout, 12) == 0)
                            {
                                fhostCmdResp->cmdru.stats.txFrames = atoi(strout + 12);
                                DPRINT_INFO("TX frames found : %d\r\n", fhostCmdResp->cmdru.stats.txFrames);
                            }
                            else
                            {
                                DPRINT_ERR("Error No TX frames\r\n");
                            }

                            // read RX frames
                            fgets(strout, sizeof(strout) - 1, tmpfile);

                            if (strncmp("RX frames : ", strout, 12) == 0)
                            {
                                fhostCmdResp->cmdru.stats.rxFrames = atoi(strout + 12);
                                DPRINT_INFO("RX frames found : %d\r\n", fhostCmdResp->cmdru.stats.rxFrames);
                            }
                            else
                            {
                                DPRINT_ERR("Error No RX frames\r\n");
                            }

                             // read TX bytes
                            fgets(strout, sizeof(strout) - 1, tmpfile);
                            if (strncmp("TX bytes : ", strout, 11) == 0)
                            {
                                fhostCmdResp->cmdru.stats.txPayloadBytes = atoi(strout + 11);
                                DPRINT_INFO("TX bytes found : %llu\r\n", fhostCmdResp->cmdru.stats.txPayloadBytes);
                            }
                            else
                            {
                                DPRINT_ERR("Error No TX bytes\r\n");
                            }

                            // read RX bytes
                            fgets(strout, sizeof(strout) - 1, tmpfile);
                            if (strncmp("RX bytes : ", strout, 11) == 0)
                            {
                                fhostCmdResp->cmdru.stats.rxPayloadBytes = atoi(strout + 11);
                                DPRINT_INFO("RX bytes found : %llu\r\n", fhostCmdResp->cmdru.stats.rxPayloadBytes);
                            }
                            else
                            {
                                DPRINT_ERR("Error No RX bytes\r\n");
                            }
                            // skip throughput
                            fgets(strout, sizeof(strout) - 1, tmpfile);
                            // skip expected frames
                            fgets(strout, sizeof(strout) - 1, tmpfile);
                            // skip lost frames
                            fgets(strout, sizeof(strout) - 1, tmpfile);
                            // read unordered frames
                            fgets(strout, sizeof(strout) - 1, tmpfile);
                            if (strncmp("Unordered : ", strout, 12) == 0)
                            {
                                fhostCmdResp->cmdru.stats.outOfSequenceFrames = atoi(strout + 12);
                                DPRINT_INFO("Unordered frames found : %d\r\n", fhostCmdResp->cmdru.stats.outOfSequenceFrames);
                            }
                            else
                            {
                                DPRINT_ERR("Error No out Of Sequence Frames\r\n");
                            }
                        }
                        else if (strncmp("Can't stop stream : ", strout, 20) == 0)
                        {
                            fhostCmdResp->streamId = atoi(strout + 20);
                            fhostCmdResp->status = STATUS_ERROR;
                            DPRINT_INFO("FhostCmdExecute : Can't stop stream : %d\r\n", fhostCmdResp->streamId);
                        }

                    break;

                    case WFA_DEVICE_LIST_IF_TLV:
                    {
                        char hdr[15];
                        int num_itf;
                        printf("wfa_device_list_if_tlv\n");
                        if (sscanf(strout, "[%d] %s", &num_itf, hdr) == 2)
                        {
                            strchr(hdr, ':')[0]='\0';
                            strcpy(fhostCmdResp->cmdru.ifList.ifs[num_itf], hdr);
                        }
                        else
                            strcpy(fhostCmdResp->cmdru.ifList.ifs[0], WFA_STAUT_IF);
                    }
                    break;

                    default :
                        DPRINT_ERR("cmd_tags not valid\r\n");
                    break;
                }
            }
        }
        else
        {
            DPRINT_INFO("Finish reading the device file\r\n");
            break;
        }
    }
    DPRINT_INFO("close %s\r\n", term_dev);

    fclose(tmpfile);

    return fhostCmdResp;
#endif
    return NULL;
}

static int DrvReset(void)
{
    if(DUT_TYPE == DUT_TYPE_SMAC)
    {
        // RESET SOFTMAC
        CMD_EXEC("modprobe -r rwnx_drv");
    }
    else if(DUT_TYPE == DUT_TYPE_FMAC)
    {
        //RESET FULLMAC
        CMD_EXEC("modprobe -r rwnx_fdrv");
    }
    else if(DUT_TYPE == DUT_TYPE_FHOST)
    {
        // RESET FHOST
        CMD_EXEC("modprobe -r rwnx_fhost");
    }
    return WFA_SUCCESS;
}

static int DrvReload(void)
{
    char options[512];

    if(wfa_dut_param_build_options(options, sizeof(options)) != WFA_SUCCESS)
        return WFA_FAILURE;

    if(DUT_TYPE == DUT_TYPE_SMAC)
    {
        // RELOAD SOFTMAC
        DPRINT_CONTENT_S("SOFTMAC rwnx driver reload: OOB Default\r\n");
        CMD_EXEC("modprobe rwnx_drv %s",options);
        wSLEEP(1);
    }
    else if(DUT_TYPE == DUT_TYPE_FMAC)
    {
        // RELOAD FULLMAC
        DPRINT_CONTENT_S("FULLMAC rwnx driver reload: OOB Default\r\n");
        CMD_EXEC("modprobe rwnx_fdrv %s",options);
        wSLEEP(1);
    }
    else if(DUT_TYPE == DUT_TYPE_FHOST)
    {
        // RELOAD FHOST
        DPRINT_CONTENT_S("FHOST rwnx driver reload: OOB Default\r\n");
        CMD_EXEC("modprobe rwnx_fhost %s",options);
        wSLEEP(1);
    }

    return WFA_SUCCESS;
}

