/*
 * This funciton is to retrieve a list of interfaces and return
 * the list back to Agent control.
 * ********************************************************************
 * Note: We intend to make this WLAN interface name as a hardcode name.
 * Therefore, for a particular device, you should know and change the name
 * for that device while doing porting. The MACRO "WFA_STAUT_IF" is defined in
 * the file "inc/wfa_ca.h". If the device OS is not linux-like, this most
 * likely is hardcoded just for CAPI command responses.
 * *******************************************************************
 *
 */
int wfaDeviceListIF(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
    dutCmdResponse_t *infoResp = &gGenericResp;
    dutCommand_t *ifList = (dutCommand_t *)caCmdBuf;
    caDeviceListIFResp_t *ifListResp = &infoResp->cmdru.ifList;
#ifdef __LINUX__
    char *str, string[256];
#endif
    FILE *tmpfd = NULL;
    int i = 0;

    DPRINT_IN_FUNC();
    ifList->cmdsu.iftype=1;

     DPRINT_INFO("--> INTERFACE TYPE: %i\r\n", ifList->cmdsu.iftype);

     if (DUT_TYPE != DUT_TYPE_FHOST)
     {
         /* retrieve the device list */
        switch(ifList->cmdsu.iftype)
        {
            case IF_80211:
#ifdef __LINUX__
                CMD_EXEC("iw dev | grep -i Interface | cut -f2 -dI > /valid/tmp/list.txt");
                tmpfd = fopen("/valid/tmp/list.txt", "r+");
                if(tmpfd == NULL)
                {
                    infoResp->status = STATUS_ERROR;
                    WFA_ENC_TLV(WFA_DEVICE_LIST_IF_TLV, sizeof(dutCmdResponse_t), (BYTE *)infoResp, respBuf);
                    *respLen = WFA_TLV_HDR_LEN + sizeof(dutCmdResponse_t);

                    DPRINT_ERR("Error file open failed");
                    return WFA_FAILURE;
                }
                else
                {
                    for(;;)
                    {
                         if(fgets(string, 256, tmpfd) == NULL)
                         {
                                fclose(tmpfd);
                                return WFA_FAILURE;
                         }

                        str = strtok(string, " ");

                        if(strncmp(str, "nterface", 5) == 0)
                        {
                            str = strtok(NULL, " ");
                            strcpy(ifListResp->ifs[i], str);

                        i++;
                        }

                        if(fscanf(tmpfd, "%255s", string) == EOF)
                        {
                            ifListResp->iftype = IF_80211;
                            infoResp->status = STATUS_COMPLETE;
                            if (i == 0)
                                strcpy(ifListResp->ifs[i], WFA_STAUT_IF);
                            break;
                        }
                    }
                }
#else
                ifListResp->iftype = IF_80211;
                infoResp->status = STATUS_COMPLETE;
                strcpy(ifListResp->ifs[0], WFA_STAUT_IF);
#endif
                break;

            case IF_ETH:
                DPRINT_INFO("--> Type: IF_80211...\r\n");
                infoResp->status = STATUS_COMPLETE;
                ifListResp->iftype = IF_ETH;
                strcpy(ifListResp->ifs[0], "eth0");
                strcpy(ifListResp->ifs[1], "NULL");
                strcpy(ifListResp->ifs[2], "NULL");
                break;

            default:
            {
                ifListResp->iftype = IF_80211;
                infoResp->status = STATUS_COMPLETE;
                if (i == 0)
                    strcpy(ifListResp->ifs[i], WFA_STAUT_IF);
                break;
            }
        }
    }
    else
    {
        dutCmdResponse_t *fhostCmdResp;;

        ifListResp->iftype = IF_80211;
        fhostCmdResp = FhostCmdExecute("ip addr show", WFA_DEVICE_LIST_IF_TLV);
        if (fhostCmdResp != NULL)
        {
            memcpy(ifListResp->ifs, fhostCmdResp->cmdru.ifList.ifs, sizeof(ifListResp->ifs));
            free(fhostCmdResp);
        }
        else
        {
            DPRINT_ERR("Error: fhostCmdResp NULL\r\n");
        }
        infoResp->status = STATUS_COMPLETE;
    }

    WFA_ENC_TLV(WFA_DEVICE_LIST_IF_TLV, sizeof(dutCmdResponse_t), (BYTE *)infoResp, respBuf);
    *respLen = WFA_TLV_HDR_LEN + sizeof(dutCmdResponse_t);
    // WFA_ENC_TLV(WFA_DEVICE_LIST_IF_TLV, 4, (BYTE *)infoResp, respBuf);
    // *respLen = WFA_TLV_HDR_LEN + 4;

    if (tmpfd != NULL)
        fclose(tmpfd);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

int wfaStaDebugSet(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
    dutCmdResponse_t *debugResp = &gGenericResp;
    dutCommand_t *debugSet = (dutCommand_t *)caCmdBuf;

    DPRINT_IN_FUNC();

    if(debugSet->cmdsu.dbg.state == 1) /* enable */
        wfa_defined_debug |= debugSet->cmdsu.dbg.level;
    else
        wfa_defined_debug = (~debugSet->cmdsu.dbg.level & wfa_defined_debug);

    debugResp->status = STATUS_COMPLETE;
    WFA_ENC_TLV(WFA_STA_GET_INFO_TLV, sizeof(dutCmdResponse_t), (BYTE *)debugResp, respBuf);
    *respLen = WFA_TLV_HDR_LEN + sizeof(dutCmdResponse_t);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

/*
 * _wfaStaGetBSSID():
 *     This function sets the BSSID of a specific wireless I/F.
 */
static int _wfaStaGetBSSID(char* intf)
{
    //char string[64];
    int ret = WFA_FAILURE;
    //char *str;
    //FILE *tmpfd;

    // FULLMAC and SOFTMAC
    if (DUT_TYPE != DUT_TYPE_FHOST)
    {
        struct ApListStruct ap;

        memset(&ap, 0, sizeof(ap));
        ret = wlan_sta_ap_info(&ap);
        os_printf("%s %d: ret %d, channel %d\n", __func__, __LINE__, ret, ap.channel);
        if (ret == 0) {
            if (ap.channel >= 0) {
                sprintf(bssid, "%pm", ap.bssid);
                os_memcpy(bssid_bin, ap.bssid, 6);
                os_printf("%s %d: |%s|\n", __func__, __LINE__, bssid);
                ret = WFA_SUCCESS;
            }
        }
#if 0
        /* retrieve the BSSID */
        CMD_EXEC("wpa_cli -i%s status > /valid/tmp/bssid.txt", intf);
        tmpfd = fopen("/valid/tmp/bssid.txt", "r+");

        if(tmpfd == NULL)
        {
            DPRINT_ERR("Error: file open failed\r\n");
            return ret;
        }

        for(;;)
        {
            if(fscanf(tmpfd, "%63s", string) == EOF)
            {
                strcpy(bssid, "00:00:00:00:00:00");
                ret = WFA_SUCCESS;
                break;
            }

            if(strncmp(string, "bssid", 5) == 0)
            {
                str = strtok(string, "=");
                str = strtok(NULL, "=");
                if(str != NULL)
                {
                    strcpy(bssid, str);
                    ret = WFA_SUCCESS;
                    break;
                }
            }
        }
        fclose(tmpfd);
#endif
    }
    else
    {
        dutCmdResponse_t *fhostCmdResp = NULL;

        fhostCmdResp = FhostCmdExecute(NULL, WFA_STA_GET_BSSID_TLV);

        if (fhostCmdResp != NULL)
        {
            strcpy(bssid, fhostCmdResp->cmdru.bssid);
            free(fhostCmdResp);
            ret = WFA_SUCCESS;
        }
        else
        {
            DPRINT_ERR("Error: fhostCmdResp NULL\r\n");
        }
    }

    return ret;
}

union rwnx_mcs_index {
    struct {
        u32 mcs : 3;
        u32 nss : 2;
    } ht;
    struct {
        u32 mcs : 4;
        u32 nss : 3;
    } vht;
    struct {
        u32 mcs : 4;
        u32 nss : 3;
    } he;
    u32 legacy : 7;
};

/* c.f RW-WLAN-nX-MAC-HW-UM */
union rwnx_rate_ctrl_info {
    struct {
        u32 mcsIndexTx      : 7;
        u32 bwTx            : 2;
        u32 giAndPreTypeTx  : 2;
        u32 formatModTx     : 3;
        #if 1//def CONFIG_RWNX_FULLMAC
        u32 dcmTx           : 1;
        #else
        u32 navProtFrmEx    : 3;
        u32 mcsIndexProtTx  : 7;
        u32 bwProtTx        : 2;
        u32 formatModProtTx : 3;
        u32 nRetry          : 3;
        #endif
    };
    u32 value;
};

/* Rate and policy table */

#define N_CCK  8
#define N_OFDM 8
#define N_HT   (8 * 2 * 2 * 4)
#define N_VHT  (10 * 4 * 2 * 8)
#define N_HE_SU (12 * 4 * 3 * 8)
#define N_HE_MU (12 * 6 * 3 * 8)


// Values of the FORMAT_MOD fields
/// Non-HT format
#define FORMATMOD_NON_HT          0
/// Non-HT duplicate OFDM format
#define FORMATMOD_NON_HT_DUP_OFDM 1
/// HT mixed mode format
#define FORMATMOD_HT_MF           2
/// HT greenfield format
#define FORMATMOD_HT_GF           3
/// VHT format
#define FORMATMOD_VHT             4
/// HE-SU format
#define FORMATMOD_HE_SU           5
/// HE-MU format
/// @note This format cannot be used in the policy table but is used when reporting HE
/// TB transmissions/MU receptions to upper layers
#define FORMATMOD_HE_MU           6
/// HE-ER format
#define FORMATMOD_HE_ER           7

static void idx_to_rate_cfg(int idx, union rwnx_rate_ctrl_info *r_cfg, int *ru_size)
{
    r_cfg->value = 0;
    if (idx < N_CCK)
    {
        r_cfg->formatModTx = FORMATMOD_NON_HT;
        r_cfg->giAndPreTypeTx = (idx & 1) << 1;
        r_cfg->mcsIndexTx = idx / 2;
    }
    else if (idx < (N_CCK + N_OFDM))
    {
        r_cfg->formatModTx = FORMATMOD_NON_HT;
        r_cfg->mcsIndexTx =  idx - N_CCK + 4;
    }
    else if (idx < (N_CCK + N_OFDM + N_HT))
    {
        union rwnx_mcs_index *r = (union rwnx_mcs_index *)r_cfg;

        idx -= (N_CCK + N_OFDM);
        r_cfg->formatModTx = FORMATMOD_HT_MF;
        r->ht.nss = idx / (8*2*2);
        r->ht.mcs = (idx % (8*2*2)) / (2*2);
        r_cfg->bwTx = ((idx % (8*2*2)) % (2*2)) / 2;
        r_cfg->giAndPreTypeTx = idx & 1;
    }
    else if (idx < (N_CCK + N_OFDM + N_HT + N_VHT))
    {
        union rwnx_mcs_index *r = (union rwnx_mcs_index *)r_cfg;

        idx -= (N_CCK + N_OFDM + N_HT);
        r_cfg->formatModTx = FORMATMOD_VHT;
        r->vht.nss = idx / (10*4*2);
        r->vht.mcs = (idx % (10*4*2)) / (4*2);
        r_cfg->bwTx = ((idx % (10*4*2)) % (4*2)) / 2;
        r_cfg->giAndPreTypeTx = idx & 1;
    }
    else if (idx < (N_CCK + N_OFDM + N_HT + N_VHT + N_HE_SU))
    {
        union rwnx_mcs_index *r = (union rwnx_mcs_index *)r_cfg;

        idx -= (N_CCK + N_OFDM + N_HT + N_VHT);
        r_cfg->formatModTx = FORMATMOD_HE_SU;
        r->vht.nss = idx / (12*4*3);
        r->vht.mcs = (idx % (12*4*3)) / (4*3);
        r_cfg->bwTx = ((idx % (12*4*3)) % (4*3)) / 3;
        r_cfg->giAndPreTypeTx = idx % 3;
    }
    else
    {
        union rwnx_mcs_index *r = (union rwnx_mcs_index *)r_cfg;

        //BK_ASSERT(ru_size == NULL);

        idx -= (N_CCK + N_OFDM + N_HT + N_VHT + N_HE_SU);
        r_cfg->formatModTx = FORMATMOD_HE_MU;
        r->vht.nss = idx / (12*6*3);
        r->vht.mcs = (idx % (12*6*3)) / (6*3);
        *ru_size = ((idx % (12*6*3)) % (6*3)) / 3;
        r_cfg->giAndPreTypeTx = idx % 3;
        r_cfg->bwTx = 0;
    }
}

/*
 * wfaStaGetBSSID():
 *     This function is to retrieve BSSID of a specific wireless I/F.
 */
int wfaStaGetBSSID(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
    dutCommand_t *cmd = (dutCommand_t*) caCmdBuf;
    dutCmdResponse_t *bssidResp = &gGenericResp;
    int mcs_fixedrate_id;

    DPRINT_IN_FUNC();

    if (_wfaStaGetBSSID(cmd->intf) == WFA_SUCCESS)
    {
        bssidResp->status = STATUS_COMPLETE;
        strcpy(bssidResp->cmdru.bssid, bssid);
    }
    else
    {
        bssidResp->status = STATUS_ERROR;

        WFA_ENC_TLV(WFA_STA_GET_BSSID_TLV, 4, (BYTE *)bssidResp, respBuf);
        *respLen = WFA_TLV_HDR_LEN + 4;

        return WFA_FAILURE;
    }

    os_printf("%s %d: program %s, mcs_fixedrate %d\n", __func__, __LINE__, wfa_program, mcs_fixedrate);

    //APPLY FIXED RATE
    //for 6.4.5: /sys/kernel/debug/ieee80211/phy0/rwnx/rc/%s/fixed_rate_idx
    if (mcs_fixedrate != 0)
    {
        //GET WFA PROGRAM
        if(os_strcasecmp(wfa_program, "HE") == 0 )
        {
            //MCS7-GI1.6us: id = 869
            mcs_fixedrate_id=869;
            //Send command
#if 0
            CMD_EXEC("echo %d > /sys/kernel/debug/ieee80211/phy0/rwnx/stations/%s/rc/fixed_rate_idx",mcs_fixedrate_id, bssidResp->cmdru.bssid);
#else
            void *sta = sta_mgmt_get_sta(bssid_bin);
            os_printf("%s %d: %pm\n", __func__, __LINE__, bssid_bin);
            if (sta) {
                union rwnx_rate_ctrl_info rate_config;


                /* Convert rate index into rate configuration */
                if ((mcs_fixedrate_id < 0) || (mcs_fixedrate_id >= (N_CCK + N_OFDM + N_HT + N_VHT + N_HE_SU)))
                {
                    // disable fixed rate
                    rate_config.value = (u32)-1;
                }
                else
                {
                    idx_to_rate_cfg(mcs_fixedrate_id, &rate_config, NULL);
                }

                os_printf("%s %d: fixed rate 0x%x\n", __func__, __LINE__, rate_config.value);
                rw_send_me_rc_set_rate(mac_sta_mgmt_get_staid(sta), rate_config.value);
            }
#endif
            wSLEEP(1);
        }
        else if(os_strcasecmp(wfa_program, "VHT") == 0 )
        {
            //GET mcs_fixedrate_id
            CMD_EXEC("rc_idx -f -t VHT -n %d -m %d -g %d -b 80", PARAM_COMMON(nss), mcs_fixedrate, PARAM_COMMON(sgi80) );
        }
        else if(os_strcasecmp(wfa_program, "HT") == 0 )
        {
            //NOT USED
        }
    }

    WFA_ENC_TLV(WFA_STA_GET_BSSID_TLV, sizeof(dutCmdResponse_t), (BYTE *)bssidResp, respBuf);
    *respLen = WFA_TLV_HDR_LEN + sizeof(dutCmdResponse_t);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

/*
 * wfaStaSetIBSS()
 *    This is to set
 *    1. ssid
 *    2. channel
 *    3. encrypType - none or wep
 *    optional
 *    4. key1
 *    5. key2
 *    6. key3
 *    7. key4
 *    8. activeIndex - 1, 2, 3, or 4
 */
int wfaStaSetIBSS(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
    caStaSetIBSS_t *setIBSS = (caStaSetIBSS_t *)caCmdBuf;
    dutCmdResponse_t *setIbssResp = &gGenericResp;
    int i;

    DPRINT_IN_FUNC();

    /*
    * disable the network first
    */
    CMD_EXEC("wpa_cli -i %s disable_network 0", setIBSS->intf);
    CMD_EXEC("wpa_cli -i %s remove_network 0", setIBSS->intf);
    CMD_EXEC("wpa_cli -i %s add_network", setIBSS->intf);

 /*
    * Set channel for IBSS
    */
    CMD_EXEC("wpa_cli -i%s frequency %i", setIBSS->intf, setIBSS->channel);
    /*
    * Tell the supplicant for IBSS mode (1)
    */
    CMD_EXEC("wpa_cli -i %s set_network 0 mode 1", setIBSS->intf);
    /*
    * set Key management to NONE (NO WPA) for plaintext or WEP
    */
    CMD_EXEC("wpa_cli -i %s set_network 0 key_mgmt NONE", setIBSS->intf);

    if(setIBSS->encpType == 1)
    {
        for(i=0; i<4; i++)
        {
            if(strlen(setIBSS->keys[i]) ==5 || strlen(setIBSS->keys[i]) == 13)
            {
                CMD_EXEC("wpa_cli -i %s set_network 0 wep_key%i \"%s\"",
                setIBSS->intf, i, setIBSS->keys[i]);
            }
        }

        i = setIBSS->activeKeyIdx;
        if(strlen(setIBSS->keys[i]) ==5 || strlen(setIBSS->keys[i]) == 13)
        {
            CMD_EXEC("wpa_cli -i %s set_network 0 wep_tx_keyidx %i",
            setIBSS->intf, setIBSS->activeKeyIdx);
        }
    }

    /*
    * set SSID
    */
    CMD_EXEC("wpa_cli -i %s set_network 0 ssid '\"%s\"'", setIBSS->intf, setIBSS->ssid);
    CMD_EXEC("wpa_cli -i %s enable_network 0", setIBSS->intf);

    setIbssResp->status = STATUS_COMPLETE;
    WFA_ENC_TLV(WFA_STA_SET_IBSS_TLV, 4, (BYTE *)setIbssResp, respBuf);
    *respLen = WFA_TLV_HDR_LEN + 4;

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

