int wfaStaSetEapFAST(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
    caStaSetEapFAST_t *setFAST= (caStaSetEapFAST_t *)caCmdBuf;
    char *ifname = setFAST->intf;
    dutCmdResponse_t *setEapFastResp = &gGenericResp;

    DPRINT_IN_FUNC();

#ifdef WFA_NEW_CLI_FORMAT
    CMD_EXEC("wfa_set_eapfast %s %s %s %s %s %s", ifname, setFAST->ssid, setFAST->username,
                                                          setFAST->passwd, setFAST->pacFileName,
                                                          setFAST->innerEAP);
#else

    CMD_EXEC("wpa_cli -i %s disable_network 0", ifname);
    CMD_EXEC("wpa_cli -i %s remove_network 0", ifname);
    CMD_EXEC("wpa_cli -i %s add_network 0", ifname);
    CMD_EXEC("wpa_cli -i %s set_network 0 key_mgmt WPA-EAP", ifname);

    if (os_strcasecmp(setFAST->keyMgmtType, "wpa2") == 0)
        CMD_EXEC("wpa_cli -i %s set_network 0 proto WPA2", ifname);
    else if (os_strcasecmp(setFAST->keyMgmtType, "wpa") == 0)
        CMD_EXEC("wpa_cli -i %s set_network 0 proto WPA", ifname);
    else
        CMD_EXEC("wpa_cli -i %s set_network 0 proto WPA WPA2 ", ifname);

    //#######################################################################################################################################
    /*encTYPE */
    if (setFAST->encrptype == ENCRYPT_TKIP)
    {
        CMD_EXEC("wpa_cli -i %s set_network 0 group \" TKIP\" ", ifname);
        CMD_EXEC("wpa_cli -i %s set_network 0 pairwise \" TKIP\"", ifname);
    }
    else if (setFAST->encrptype == ENCRYPT_AESCCMP)
    {
        CMD_EXEC("wpa_cli -i %s set_network 0 group \" CCMP TKIP\" ", ifname);
        CMD_EXEC("wpa_cli -i %s set_network 0 pairwise \" CCMP\"", ifname);
    }
    else if (setFAST->encrptype == ENCRYPT_AESCCMPTKIP)
    {
        CMD_EXEC("wpa_cli -i %s set_network 0 group \" CCMP TKIP\" ", ifname);
        CMD_EXEC("wpa_cli -i %s set_network 0 pairwise \" CCMP TKIP\"", ifname);
    }
    else
    {
        //not used
    }

    CMD_EXEC("wpa_cli -i %s set_network 0 identity '\"%s\"'", ifname, setFAST->username);
    CMD_EXEC("wpa_cli -i %s set_network 0 password '\"%s\"'", ifname, setFAST->passwd);
    CMD_EXEC("wpa_cli -i %s set_network 0 eap FAST", ifname);
    CMD_EXEC("wpa_cli -i %s set_network 0 pac_file '\"%s/%s\"'", ifname, CERTIFICATES_PATH,  setFAST->pacFileName);
    CMD_EXEC("wpa_cli -i %s set_network 0 anonymous_identity '\"anonymous\"'", ifname);
    CMD_EXEC("wpa_cli -i %s set_network 0 phase1 '\"fast_provisioning=1\"'", ifname);
    CMD_EXEC("wpa_cli -i %s set_network 0 phase2 '\"auth=%s\"'", ifname,setFAST->innerEAP);
    CMD_EXEC("wpa_cli -i %s set_network 0 ssid '\"%s\"'", ifname, setFAST->ssid);
    CMD_EXEC("wpa_cli -i %s select_network 0", ifname);
    CMD_EXEC("wpa_cli -i %s enable_network 0", ifname);
#endif

    setEapFastResp->status = STATUS_COMPLETE;
    WFA_ENC_TLV(WFA_STA_SET_EAPFAST_TLV, 4, (BYTE *)setEapFastResp, respBuf);
    *respLen = WFA_TLV_HDR_LEN + 4;

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

