int wfaStaSetSystime(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
    caStaSetSystime_t *systime = (caStaSetSystime_t *)caCmdBuf;
    dutCmdResponse_t *setSystimeResp = &gGenericResp;

    DPRINT_IN_FUNC();

    if ( systime->year >= 2035)
        systime->year = 2036;

    if ( DUT_PLATFORM == DINIV6 )
    {
        if (systime->month < 10)
            if(systime->date < 10)
                CMD_EXEC("date 0%d0%d0600%d",systime->month,systime->date,systime->year);
            else
                CMD_EXEC("date 0%d%d0600%d",systime->month,systime->date,systime->year);
        else
            if(systime->date < 10)
                CMD_EXEC("date %d0%d0600%d",systime->month,systime->date,systime->year);
            else
                CMD_EXEC("date %d%d0600%d",systime->month,systime->date,systime->year);
    }
    else
    {
        if (systime->month < 10)
            if(systime->date < 10)
                CMD_EXEC("date 0%d0%d0600%d",systime->month,systime->date,systime->year);

            else
                CMD_EXEC("date 0%d%d0600%d",systime->month,systime->date,systime->year);
        else
            if(systime->date < 10)
                CMD_EXEC("date %d0%d0600%d",systime->month,systime->date,systime->year);
            else
                CMD_EXEC("date %d%d0600%d",systime->month,systime->date,systime->year);
    }

    setSystimeResp->status = STATUS_COMPLETE;

    WFA_ENC_TLV(WFA_STA_SET_SYSTIME_TLV, 4, (BYTE *)setSystimeResp, respBuf);
    *respLen = WFA_TLV_HDR_LEN + 4;

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

int GetPhy(void)
{
    int phy=0;
    FILE *tmpfd;
    char string[256];
    CMD_EXEC("iw list | grep -i \"wiphy phy\" | cut -f2 -d\" \" |cut -f2 -d\"y\"> /valid/tmp/tmp_file.txt");

    tmpfd = fopen("/valid/tmp/tmp_file.txt", "r+");
    if(tmpfd == NULL) { return WFA_FAILURE;}
    if(fgets(string, 6, tmpfd) == NULL)
    {
        DPRINT_INFO("string null\r\n");
        fclose(tmpfd);
        return WFA_FAILURE;
    }
    phy = atoi(string);
    //DPRINT_INFO("phyid == %d--", phy);
    fclose(tmpfd);
    return phy;
}

int GetPlatformName(char *Name)
{
    FILE *tmpfd;
    char string[32];
    CMD_EXEC("uname -n > /valid/tmp/platformName");

   tmpfd = fopen("/valid/tmp/platformName", "r+");
   if(tmpfd == NULL)
    { return WFA_FAILURE;}

    if(fgets(string, 10, tmpfd) == NULL)
    {
        DPRINT_INFO("string null\r\n");
        fclose(tmpfd);
        return WFA_FAILURE;
    }
    strncpy(Name, string, 8);
    fclose(tmpfd);
    return WFA_SUCCESS;
}

int GetDateTime(char*Date)
{
    FILE *tmpfd;
    char string[32];

    if ((system("date -u +\%F\%H\%M > /valid/tmp/DateTime"))==-1){return WFA_FAILURE;}

    tmpfd = fopen("/valid/tmp/DateTime", "r+");
    if(tmpfd == NULL)
    { return WFA_FAILURE;}

    if(fgets(string, 32, tmpfd) == NULL)
    {
        DPRINT_INFO("string null\r\n");
        fclose(tmpfd);
        return WFA_FAILURE;
    }
    strncpy(Date, string,14);
    fclose(tmpfd);
    return WFA_SUCCESS;
}

/*  PresetTestParams()
 * This function is to configure the basic settings of the Station
 * reset the SW
 * Set SUpplicant
 * Set RTS and Fragmentation Threshold
 * Set power save mode
 * Set Wmm
 */

int wfaStaPresetParams(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
    dutCmdResponse_t *PresetParamsResp = &gGenericResp;
    caStaPresetParameters_t *presetParams = (caStaPresetParameters_t *)caCmdBuf;
    BYTE presetDone = 1;
#ifndef CONFIG_FREERTOS
    int phyId=0;
#endif
    // int PARAM_COMMON(use_2040]=0;

    DPRINT_IN_FUNC();

#ifndef CONFIG_FREERTOS
    if (iteration != 0 && DUT_TYPE != DUT_TYPE_FHOST)
    {
        // need to make your own command available for this, here is only an example
        CMD_EXEC("wpa_cli -i %s disconnect", presetParams->intf);
        wSLEEP(5);

        CMD_EXEC("wpa_cli -i %s terminate", presetParams->intf);
        wSLEEP(2);
    }
    // if it's not the first time to preset parameters and it is concerned FHOST
    if (iteration != 0 && DUT_TYPE == DUT_TYPE_FHOST)
    {
        CMD_EXEC("rwnx_term wpa_cli terminate");
        wSLEEP(2);
    }

    // FULLMAC and SOFTMAC
    if (DUT_TYPE != DUT_TYPE_FHOST)
    {
        //Configure 20/40 MHz mode
        if(DUT_WIDTH==20){PARAM_COMMON(use_2040) = 0;}
        else if (DUT_WIDTH==40){PARAM_COMMON(use_2040) = 1;}
        else{PARAM_COMMON(use_2040) = 1;}

        if (PARAM_SETUP(bridge)==1)
        {
            // Network bridge setup only - now takes into account wlan0 ip set
            DPRINT_BOX("### Network bridge setup... ###" );
            CMD_EXEC("./bridge_setup.sh %d set",DUT_IP_IDX);
            wSLEEP(3);
        }
    }

#ifndef CONFIG_EXT_WIFI
    // RESET driver
    if (DrvReset() != WFA_SUCCESS)
    {
        return WFA_FAILURE;
    }
    // RELOAD driver by default parameters
    if (DrvReload() != WFA_SUCCESS)
    {
        return WFA_FAILURE;
    }
#else
    CMD_EXEC("/valid/bin/ath.sh");
#endif

    // for FULLMAC and SOFTMAC
    if (DUT_TYPE != DUT_TYPE_FHOST)
    {
        /* Find phyId which may change each time driver is reset*/
        phyId = GetPhy();
        CMD_EXEC("ifconfig %s up", presetParams->intf);
        wSLEEP(2);

        //UMH
//        CMD_EXEC("echo /usr/bin/rwnx_umh.sh > /sys/kernel/debug/ieee80211/phy%d/rwnx/um_helper",phyId);
//        wSLEEP(2);

        //SET DIAG
//        CMD_EXEC("rwnx_setdiags.sh 1c 25");
//        wSLEEP(1);
//
//        CMD_EXEC("rwnx_setdiags.sh -fpgab 0f");
//        wSLEEP(1);

        CMD_EXEC("pkill -9 iperf");
        wSLEEP(2);
    }

    iteration ++;

    // start supplicant for FULLMAC and SOFTMAC
    if (DUT_TYPE != DUT_TYPE_FHOST)
    {
        /* start supplicant */
        if(presetParams->supplicant==eWpaSupplicant)
        {
            printf("#_INFO_#:Start WPA Supplicant\n");
            //Enable wpa supplicant log
            if (PARAM_SETUP(debug)==1)
            {
                CMD_EXEC("wpa_supplicant -B -Dnl80211 -i%s -c /valid/etc/wpa_supplicant.conf -dd -t -K -f /tmp/wpaSupplicant_%d.txt", presetParams->intf,iteration);
                wSLEEP(5);
            }
            else
            {
                CMD_EXEC("wpa_supplicant -B -Dnl80211 -i%s -c /valid/etc/wpa_supplicant.conf -qq ", presetParams->intf);
                wSLEEP(5);
            }
        }
        else if(presetParams->supplicant==eDefault)
        {
            printf("#_INFO_#:Start Default Supplicant\n");
            //Enable wpa supplicant log
            if (PARAM_SETUP(debug)==1)
            {
                CMD_EXEC("wpa_supplicant -B -Dnl80211 -i%s -c /valid/etc/wpa_supplicant.conf -dd -t -K -f /tmp/wpaSupplicant_%d.txt", presetParams->intf,iteration);
                wSLEEP(5);
            }
            else
            {
                CMD_EXEC("wpa_supplicant -B -Dnl80211 -i%s -c /valid/etc/wpa_supplicant.conf -qq ", presetParams->intf);
                wSLEEP(5);
            }
        }
    }
    // start supplicant for FHOST
    else
    {
        CMD_EXEC("rwnx_term wpa_supplicant");
    }

    // FULLMAC and SOFTMAC
    if (DUT_TYPE != DUT_TYPE_FHOST)
    {
        /* avoid sta to connect automatically*/
        if (presetParams->autoCFlag)
        {
            CMD_EXEC("wpa_cli -i%s sta_autoconnect %d" , presetParams->intf,presetParams->autoconnect);
        }

        /* enable  power save*/
        if(presetParams->psFlag)
        {
            if ((presetParams->legacyPowerSave == 1))
                CMD_EXEC("iw dev %s set power_save on ", presetParams->intf);
            else
                CMD_EXEC("iw dev %s set power_save off ", presetParams->intf);
        }

        /*set rts threshold*/
        if(presetParams->rtsFlag)
        {
            CMD_EXEC("iw phy phy%d set rts %d ",phyId,presetParams->rtsThreshold);
        }

        if(presetParams->fragFlag)
        {
            CMD_EXEC("iw phy phy%d set frag %d ",phyId, presetParams->fragThreshold);
        }
        if(presetParams->reset == eResetProg11n)
        {
            CMD_EXEC("wpa_cli -i%s remove_network 0 ", presetParams->intf);
        }

        //MBO
        if(presetParams->roamingFlag==1)
        {
            roaming_mbo_val = presetParams->roaming;
            printf("#_INFO_#:Disabling roaming...\n");
            //CMD_EXEC("wpa_cli -i%s set roaming %d ", presetParams->intf, presetParams->roaming);
        }
        if(presetParams->Ch_Pref_Flag==1)
        {
            if(presetParams->Ch_Reason_Code==0){
                Ch_Op_Class1 = presetParams->Ch_Op_Class;
                Ch_Pref_Num1 = presetParams->Ch_Pref_Num;
                Ch_Pref1 = presetParams->Ch_Pref;
                Ch_Reason_Code1 = presetParams->Ch_Reason_Code;
            }else{
                Ch_Op_Class2 = presetParams->Ch_Op_Class;
                Ch_Pref_Num2 = presetParams->Ch_Pref_Num;
                Ch_Pref2 = presetParams->Ch_Pref;
                Ch_Reason_Code2 = presetParams->Ch_Reason_Code;
            }
            Ch_Pref_Flag=1;
        }
    }
    else
    {
        if(presetParams->reset == eResetProg11n)
        {
            CMD_EXEC("rwnx_term wpa_cli remove_network 0 ");
        }
    }
#else
    if (iteration != 0)
    {
        cmd_wlan_sta_exec("disconnect");
        wSLEEP(1);
        cmd_wlan_sta_exec("disable");
        wSLEEP(1);
    }

    iteration ++;

    // start supplicant for FULLMAC and SOFTMAC
    cmd_wlan_sta_exec("enable");

    //MBO
    if(presetParams->roamingFlag==1)
    {
        roaming_mbo_val = presetParams->roaming;
        printf("#_INFO_#:Disabling roaming...\n");
        //CMD_EXEC("wpa_cli -i%s set roaming %d ", presetParams->intf, presetParams->roaming);
    }
    if(presetParams->Ch_Pref_Flag==1)
    {
        if(presetParams->Ch_Reason_Code==0){
            Ch_Op_Class1 = presetParams->Ch_Op_Class;
            Ch_Pref_Num1 = presetParams->Ch_Pref_Num;
            Ch_Pref1 = presetParams->Ch_Pref;
            Ch_Reason_Code1 = presetParams->Ch_Reason_Code;
        }else{
            Ch_Op_Class2 = presetParams->Ch_Op_Class;
            Ch_Pref_Num2 = presetParams->Ch_Pref_Num;
            Ch_Pref2 = presetParams->Ch_Pref;
            Ch_Reason_Code2 = presetParams->Ch_Reason_Code;
        }
        Ch_Pref_Flag=1;
    }
#endif

    if (presetDone)
    {
        PresetParamsResp->status = STATUS_COMPLETE;
    }
    else
    {
        PresetParamsResp->status = STATUS_INVALID;
    }

    WFA_ENC_TLV(WFA_STA_PRESET_PARAMETERS_TLV, 4, (BYTE *)PresetParamsResp, respBuf);
    *respLen = WFA_TLV_HDR_LEN + 4;

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

