/* wfaStaResetDefault()
 * this function is to clear the sw environment.
 * disconnect the station from the AP
 * remove the driver
 * add the driver
 */
int wfaStaResetDefault(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
    caStaResetDefault_t *reset = (caStaResetDefault_t *)caCmdBuf;
    dutCmdResponse_t *ResetResp = &gGenericResp;
    char *ifname = reset->intf;
    iteration ++;
    int dut_mode = 2;
    DPRINT_IN_FUNC();

    //#######################################################################################################################################
    //#############################################  LOAD RW DRIVER / START SUPPLICANT ######################################################
    //#######################################################################################################################################
    if (RestartDUT(ifname,dut_mode) == WFA_FAILURE)
        return WFA_FAILURE;

    if (!strcmp(reset->prog, "PMF"))
        wfa_prog = PROG_TYPE_PMF;
    else
        wfa_prog = PROG_TYPE_GEN;

    ResetResp->status = STATUS_COMPLETE;
    WFA_ENC_TLV(WFA_STA_RESET_DEFAULT_TLV, 4, (BYTE *)ResetResp, respBuf);
    *respLen = WFA_TLV_HDR_LEN + 4;

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
 }

/* Execute CLI, read the status from Environment variable */
int wfaExecuteCLI(char *CLI)
{
    char *retstr;
    int sys_err;

    DPRINT_IN_FUNC();

    if ((sys_err = system(CLI)) == -1)
    {
        return WFA_FAILURE;
    }

    retstr = getenv("WFA_CLI_STATUS");
    DPRINT_INFO("-->CLI status %s\r\n", retstr);

    DPRINT_OUT_FUNC();

    return atoi(retstr);
}

/**
 * PING_DEBUG: Enable debugging for PING.
 */
#ifndef PING_DEBUG
#define PING_DEBUG     LWIP_DBG_ON
#endif

/** ping receive timeout - in milliseconds */
#define PING_RCV_TIMEO 2000
/** ping delay - in milliseconds */
#define PING_DELAY     1000

/** ping identifier - must fit on a u16_t */
#ifndef PING_ID
#define PING_ID        0xAFAF
#endif

/** ping additional data size to include in the packet */
#ifndef PING_DATA_SIZE
#define PING_DATA_SIZE 32
#endif

/* ping variables */
static u16_t ping_seq_num;
struct _ip_addr
{
    uint8_t addr0, addr1, addr2, addr3;
};

/** Prepare a echo ICMP request */
static void ping_prepare_echo( struct icmp_echo_hdr *iecho, u16_t len)
{
    size_t i;
    size_t data_len = len - sizeof(struct icmp_echo_hdr);

    ICMPH_TYPE_SET(iecho, ICMP_ECHO);
    ICMPH_CODE_SET(iecho, 0);
    iecho->chksum = 0;
    iecho->id     = PING_ID;
    iecho->seqno  = htons(++ping_seq_num);

    /* fill the additional data buffer with some data */
    for (i = 0; i < data_len; i++)
    {
        ((char*) iecho)[sizeof(struct icmp_echo_hdr) + i] = (char) i;
    }

    iecho->chksum = inet_chksum(iecho, len);
}

/* Ping using the socket ip */
static err_t ping_send(int s, ip_addr_t *addr, int size)
{
    int err;
    struct icmp_echo_hdr *iecho;
    struct sockaddr_in to;
    int ping_size = sizeof(struct icmp_echo_hdr) + size;
    LWIP_ASSERT("ping_size is too big", ping_size <= 0xffff);

    iecho = (struct icmp_echo_hdr *)os_malloc((mem_size_t)ping_size);
    if (!iecho) {
        return ERR_MEM;
    }
    ping_prepare_echo(iecho, (u16_t) ping_size);

    to.sin_len = sizeof(to);
    to.sin_family = AF_INET;
    to.sin_addr.s_addr = addr->addr;

    err = lwip_sendto(s, iecho, ping_size, 0, (struct sockaddr*) &to, sizeof(to));
    os_free(iecho);

    return (err == ping_size ? ERR_OK : ERR_VAL);
}

static int ping_recv(int s, int *ttl, char *buf, int bufLen)
{
    int fromlen = sizeof(struct sockaddr_in), len;
    struct sockaddr_in from;
    struct ip_hdr *iphdr;
    struct icmp_echo_hdr *iecho;

    while ((len = lwip_recvfrom(s, buf, bufLen, 0, (struct sockaddr*) &from, (socklen_t*) &fromlen)) > 0)
    {
        if (len >= (int)(sizeof(struct ip_hdr) + sizeof(struct icmp_echo_hdr)))
        {
            iphdr = (struct ip_hdr *) buf;
            iecho = (struct icmp_echo_hdr *) (buf + (IPH_HL(iphdr) * 4));
            if ((iecho->id == PING_ID) && (iecho->seqno == htons(ping_seq_num)))
            {
                *ttl = iphdr->_ttl;
                return len;
            }
        }
    }

    return len;
}

struct wfaPingThreadInfo {
    char dipaddr[IPV4_ADDRESS_STRING_LEN];  /* destination/remote ip address */
    float interval;
    int rate;
    int duration;
    int framesize;
};

static int stopPingFlag = 0;
static int wfaSentCount = 0;
static int wfaRecvCount = 0;

int _wfaSendPing(struct wfaPingThreadInfo *info, char *target_name, float interval, uint32_t duration, size_t size)
{
    int s, ttl=0, recv_len;
    struct timeval timeout = { PING_RCV_TIMEO / 1000, PING_RCV_TIMEO % 1000 };
    ip_addr_t target_addr;
    uint32_t send_times;
    uint32_t recv_start_tick;
    struct addrinfo hint, *res = NULL;
    struct sockaddr_in *h = NULL;
    struct in_addr ina;
    int ret = -1;
    int times = duration / interval;
    if (size > 1000)
        size = 1000;
    char *recv_buf = os_malloc(size + 40);

    send_times = 0;
    ping_seq_num = 0;
    wfaSentCount = wfaRecvCount = 0;

    os_printf("%s: interval %f, duration %d, times %d, size %d\n", __func__, interval, duration, times, size);
    if (!recv_buf)
        goto out;

    memset(&hint, 0, sizeof(hint));
    /* convert URL to IP */
    if (lwip_getaddrinfo(target_name, NULL, &hint, &res) != 0)
    {
        LWIP_DEBUGF( PING_DEBUG, ("ping: unknown host\n"));
        goto out;
    }
    memcpy(&h, &res->ai_addr, sizeof(struct sockaddr_in *));
    memcpy(&ina, &h->sin_addr, sizeof(ina));
    lwip_freeaddrinfo(res);
    if (inet_aton(inet_ntoa(ina), &target_addr) == 0)
    {
        LWIP_DEBUGF( PING_DEBUG, ("ping: unknown host\n"));
        goto out;
    }
    /* new a socket */
    if ((s = lwip_socket(AF_INET, SOCK_RAW, IP_PROTO_ICMP)) < 0)
    {
        LWIP_DEBUGF( PING_DEBUG, ("ping: create socket failed\n"));
        goto out;
    }

    lwip_setsockopt(s, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(struct timeval));

    while (!stopPingFlag)
    {
        wfaSentCount++;
        if (ping_send(s, &target_addr, size) == ERR_OK)
        {
            recv_start_tick = sys_now();

            if ((recv_len = ping_recv(s, &ttl, recv_buf, size)) >= 0)
            {
                LWIP_DEBUGF( PING_DEBUG, ("%d bytes from %s icmp_seq=%d ttl=%d time=%d ticks\n", recv_len, inet_ntoa(ina), send_times,
                        ttl, sys_now() - recv_start_tick));
                wfaRecvCount++;
            }
            else
            {
                LWIP_DEBUGF( PING_DEBUG, ("From %s icmp_seq=%d timeout\n", inet_ntoa(ina), send_times));
            }
        }
        else
        {
            LWIP_DEBUGF( PING_DEBUG, ("Send %s - error\n", inet_ntoa(ina)));
        }

        send_times++;
        if (send_times >= times)
        {
            /* send ping times reached, stop */
            break;
        }
        sys_msleep(interval*PING_DELAY);
    }

    lwip_close(s);
    os_free(recv_buf);

    ret = 0;

out:
    os_free(info);

    return ret;
}

#define CONFIG_PING_THREAD   1

void __wfaSendPing(void *param)
{
    struct wfaPingThreadInfo *info = param;
    _wfaSendPing(info, info->dipaddr, info->interval, info->duration, info->framesize);
    rtos_delete_thread(NULL);
}

/* Supporting Functions
 * this function is to configure and send ping, it supports:
 * unicast
 * broadcast
 * multicast
 */

int wfaSendPing(tgPingStart_t *staPing, float *interval, int streamid)
{
//    int totalpkts;
    char cmdStr[256];
    char addr[64];
    char bflag[] = "-b";
    char qflag[]="-q";
    char *tmpstr;
    int inum=0;

    // ping stream id
    int id = -1;

    DPRINT_IN_FUNC();

//    totalpkts = (int) ((float) staPing->duration * staPing->frameRate);
    strcpy(addr,staPing->dipaddr);

    DPRINT_BOX("PARAMS -->>> Send Ping ..." );
    DPRINT_INFO("--> The addr is %s \r\n",staPing->dipaddr);
    DPRINT_INFO("--> Duration: %d \r\n",staPing->duration);
    DPRINT_INFO("--> Interval: %f\r\n", *interval);


    tmpstr = strtok(addr, ".");
    inum = atoi(tmpstr);

    if(inum >= 224 && inum <= 239) // multicast
    {
        DPRINT_INFO("--> Type = Multicast\r\n");
        BcastPing = 1;
        memset(bflag, 0, strlen(bflag));
        memset(qflag, 0, strlen(qflag));
    }
    else // if not MC, check if it is BC address
    {
        strtok(NULL, ".");
        strtok(NULL, ".");
        tmpstr = strtok(NULL, " ");
        inum = atoi(tmpstr);

        if(inum != 255)
        {
            memset(bflag, 0, strlen(bflag));
        }
        else
        {
            DPRINT_INFO("--> Type = Broadcast\r\n");
            memset(qflag, 0, strlen(qflag));
            BcastPing = 1;
        }
    }
    DPRINT_CONTENT("**********************************************************\r\n");
    // FHOST
    if (DUT_TYPE == DUT_TYPE_FHOST)
    {
        dutCmdResponse_t *fhostCmdResp = NULL;
        // write the command string in the device file to execute it
        sprintf(cmdStr, "ping %s -s %d -d %d -r %f -G",
                staPing->dipaddr, staPing->frameSize, staPing->duration, staPing->frameRate);

        fhostCmdResp = FhostCmdExecute(cmdStr, WFA_TRAFFIC_SEND_PING_TLV);

        if (fhostCmdResp != NULL)
        {
            id = fhostCmdResp->streamId;
            free(fhostCmdResp);
        }
        else
        {
            DPRINT_ERR("fhostCmdResp NULL\r\n");
        }
    }
    // FULLMAC and SOFTMAC
    else
    {
#if 0

       if(BcastPing == 1)
        {
            sprintf(cmdStr, "echo streamid=%i > /valid/tmp/spout_%d.txt; /valid/bin/wfaping.sh -I%s %s -L %s -i %f -c %i -s %i %s >> /valid/tmp/spout_%d.txt 2>/dev/null",
            streamid,streamid,staPing->ifname,bflag, staPing->dipaddr, *interval, totalpkts, staPing->frameSize,qflag,streamid);
        }
        else
        {
            sprintf(cmdStr, "echo streamid=%i > /valid/tmp/spout_%d.txt; /valid/bin/wfaping.sh %s -L %s -i %f -c %i -s %i %s >> /valid/tmp/spout_%d.txt 2>/dev/null",
            streamid,streamid,bflag, staPing->dipaddr, *interval, totalpkts, staPing->frameSize,qflag,streamid);
        }
       DPRINT_CMD(cmdStr);

        //if ((system(cmdStr))== -1)
            DPRINT_ERR("Error while executing system function \r\n");

        sprintf(cmdStr, "/valid/bin/updatepid.sh /valid/tmp/spout_%d.txt",streamid);
        DPRINT_CMD(cmdStr);
#else
        os_printf("frameSize %d, duration %d, rate %d\n", staPing->frameSize, staPing->duration, staPing->frameRate);
#if CONFIG_PING_THREAD
        beken_thread_t wfaping_thd = NULL;
        struct wfaPingThreadInfo *info = os_malloc(sizeof(*info));

        if (info) {
            os_memcpy(info->dipaddr, staPing->dipaddr, sizeof(info->dipaddr));
            info->interval = *interval;
            info->rate = staPing->frameRate;
            info->duration = staPing->duration;
            info->framesize = staPing->frameSize;
            stopPingFlag = 0;
            rtos_create_thread(&wfaping_thd, BEKEN_APPLICATION_PRIORITY, "__wfaSendPing",
                               __wfaSendPing, 2048, info);

        }
#else
        _wfaSendPing(staPing->dipaddr, *interval, staPing->duration, staPing->frameSize);
#endif
#endif
    }

    DPRINT_OUT_FUNC();

    return id;
}

int wfaStopPing(dutCmdResponse_t *stpResp, tgPingStop_t* stoping)
{
//    char strout[256];
//    FILE *tmpfile = NULL;
    char cmdStr[128];
//    int sys_err;

    DPRINT_IN_FUNC();

    // FHOST
    if (DUT_TYPE == DUT_TYPE_FHOST)
    {
        dutCmdResponse_t *fhostCmdResp = NULL;
        // write the command string in the device file to execute it
        sprintf(cmdStr, "ping stop %d",stoping->streamid);

        fhostCmdResp = FhostCmdExecute(cmdStr, WFA_TRAFFIC_STOP_PING_TLV);

        if (fhostCmdResp != NULL)
        {
            stpResp->cmdru.pingStp.sendCnt = fhostCmdResp->cmdru.pingStp.sendCnt;
            DPRINT_INFO("--> Transmitted: %i\r\n", stpResp->cmdru.pingStp.sendCnt);
            stpResp->cmdru.pingStp.repliedCnt =  fhostCmdResp->cmdru.pingStp.repliedCnt;
            DPRINT_INFO("--> Received: %i\r\n", stpResp->cmdru.pingStp.repliedCnt);
            free(fhostCmdResp);
        }
        else
        {
            DPRINT_ERR("fhostCmdResp NULL\r\n");
        }
    }
    // FULLMAC and SOFTMAC
    else
    {
        DPRINT_BOX("PARAMS -->>> Ping stop id ..." );
#if 0
        sprintf(cmdStr, "/valid/bin/getpid.sh /valid/tmp/spout_%d.txt /valid/tmp/pid.txt",stoping->streamid);
          if ((sys_err = system(cmdStr))== -1){return WFA_FAILURE;}

        DPRINT_CMD(cmdStr);

        if ((sys_err = system("/valid/bin/stoping.sh /valid/tmp/pingpid.txt ; sleep 2"))== -1){return WFA_FAILURE;}

        if( BcastPing == 1)
        {
          sprintf(cmdStr, "/valid/bin/getpstats.sh /valid/tmp/spout_%d.txt %s",stoping->streamid,stoping->rcvResp);
          BcastPing = 0;
        }
        else
            sprintf(cmdStr,"/valid/bin/getpstats.sh /valid/tmp/spout_%d.txt",stoping->streamid);
        if ((sys_err = system(cmdStr))== -1){return WFA_FAILURE;}

        DPRINT_CMD(cmdStr);

        tmpfile = fopen("/valid/tmp/stpsta.txt", "r+");

        if(tmpfile == NULL)
        {
            return WFA_FAILURE;
        }

        if(fscanf(tmpfile, "%s", strout) != EOF)
        {
            if(*strout == '\0')
            {
                stpResp->cmdru.pingStp.sendCnt = 0;
            }

            else
                stpResp->cmdru.pingStp.sendCnt = atoi(strout);
        }
        DPRINT_INFO("--> Transmitted: %i", stpResp->cmdru.pingStp.sendCnt);


        if(fscanf(tmpfile, "%s", strout) != EOF)
        {
            if(*strout == '\0')
            {
                stpResp->cmdru.pingStp.repliedCnt = 0;
            }
            else
            {
                stpResp->cmdru.pingStp.repliedCnt = atoi(strout);
            }
        }
        DPRINT_INFO("--> Received: %i\r\n", stpResp->cmdru.pingStp.repliedCnt);
        DPRINT_CONTENT("**********************************************************\r\n");
        fclose(tmpfile);
#else
#if CONFIG_PING_THREAD
        stopPingFlag = 1;
#endif

        stpResp->cmdru.pingStp.sendCnt = wfaSentCount;
        stpResp->cmdru.pingStp.repliedCnt = wfaRecvCount;
#endif
    }

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}


/*
 * wfaStaGetP2pDevAddress():
 */
int wfaStaGetP2pDevAddress(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
    dutCmdResponse_t *DevaddrResp = &gGenericResp;
    char string[64];
    dutCommand_t *cmd = (dutCommand_t*) caCmdBuf;
    char *str;
    FILE *tmpfd;

    DPRINT_IN_FUNC();

    /* retrieve the p2pdEVICE ADDRESS */
    CMD_EXEC("wpa_cli -i%s status > /valid/tmp/tmp_file.txt",cmd->intf );
    tmpfd = fopen("/valid/tmp/tmp_file.txt", "r+");

    if(tmpfd == NULL)
    {
        DevaddrResp->status = STATUS_ERROR;
        WFA_ENC_TLV(WFA_STA_P2P_GET_DEV_ADDRESS_TLV, 4, (BYTE *)DevaddrResp, respBuf);
        *respLen = WFA_TLV_HDR_LEN + 4;

        DPRINT_ERR("/valid/tmp/tmp_file.txt file open failed\r\n");
        return WFA_FAILURE;
    }

    for(;;)
    {
        if(fscanf(tmpfd, "%63s", string) == EOF)
        {
            DevaddrResp->status = STATUS_COMPLETE;
            strcpy(DevaddrResp->cmdru.devid, "00:00:00:00:00:00");
            break;
        }

        if(strncmp(string, "p2p_device_address", 5) == 0)
        {
            str = strtok(string, "=");
            str = strtok(NULL, "=");
            if(str != NULL)
            {
                strcpy(DevaddrResp->cmdru.devid, str);
                DevaddrResp->status = STATUS_COMPLETE;
                break;
            }
        }
    }
    WFA_ENC_TLV(WFA_STA_P2P_GET_DEV_ADDRESS_TLV, sizeof(dutCmdResponse_t), (BYTE *)DevaddrResp, respBuf);
    *respLen = WFA_TLV_HDR_LEN + sizeof(dutCmdResponse_t);

    fclose(tmpfd);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

/*
 * wfaStaSetP2p():
 */
int wfaStaSetP2p(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
    dutCmdResponse_t *infoResp = &gGenericResp;
    caStaSetP2p_t *getStaSetP2p = (caStaSetP2p_t *)caCmdBuf;

    //   if(Store_Inv_Req==0)
    //   {
    DPRINT_IN_FUNC();

    if (getStaSetP2p->listen_chn_flag)
    {
        CMD_EXEC("wpa_cli -i%s p2p_set listen_channel %d",getStaSetP2p->intf, getStaSetP2p->listen_chn );
        wSLEEP(5);
    }

    if (getStaSetP2p->persistent_flag)
    {
        CMD_EXEC("wpa_cli -i%s set persistent_reconnect %d",getStaSetP2p->intf, getStaSetP2p->persistent );
        persistent_flag = 1;
        persistent_val=getStaSetP2p->persistent;
        wSLEEP(1);
    }

    if (getStaSetP2p->intra_bss_flag)
    {
        CMD_EXEC("wpa_cli -i%s set p2p_intra_bss %d",getStaSetP2p->intf, getStaSetP2p->intra_bss );
        wSLEEP(1);
    }

    if ((getStaSetP2p->noa_duration_flag) && (getStaSetP2p->noa_interval_flag) && (getStaSetP2p->noa_count_flag))
    {
        CMD_EXEC("echo 'count=%d interval=%d duration=%d dyn=0' > /sys/kernel/debug/ieee80211/phy0/rwnx/p2p/noa",getStaSetP2p->noa_count, getStaSetP2p->noa_interval , getStaSetP2p->noa_duration);
    }

    if (getStaSetP2p->concurrency_flag)
    {
        DPRINT_INFO("NOT CONFIGURABLE ON DUT   getStaSetP2p->concurrency\r\n");
    }

    if (getStaSetP2p->p2p_invitation_flag)
    {
        DPRINT_INFO("NOT CONFIGURABLE ON DUT   getStaSetP2p->p2p_invitation\r\n");
    }

    if (getStaSetP2p->bcn_int_flag)
    {
        DPRINT_INFO("NOT CONFIGURABLE ON DUT   getStaSetP2p->bcn_int\r\n");
    }

    if ((getStaSetP2p->ext_listen_time_int_flag) && (getStaSetP2p->ext_listen_time_period_flag))
    {
        CMD_EXEC("wpa_cli -i%s p2p_ext_listen %d %d",getStaSetP2p->intf, getStaSetP2p->ext_listen_time_period , getStaSetP2p->ext_listen_time_int);
        wSLEEP(1);
    }

    if (getStaSetP2p->discoverability_flag)
    {
        CMD_EXEC("wpa_cli -i%s p2p_set discoverability %d",getStaSetP2p->intf, getStaSetP2p->discoverability );
    }

    if (getStaSetP2p->service_discovry_flag)
    {
        DPRINT_INFO("NOT CONFIGURABLE ON DUT   getStaSetP2p->service_discovery\r\n");
    }

    if (getStaSetP2p->crossconnection_flag)
    {
        DPRINT_INFO("NOT CONFIGURABLE ON DUT   getStaSetP2p->crossconnection\r\n");
    }

    if (getStaSetP2p->p2pmanaged_flag)
    {
        CMD_EXEC("wpa_cli -i%s p2p_set managed %d",getStaSetP2p->intf, getStaSetP2p->p2pmanaged);
    }

    if (getStaSetP2p->go_apsd_flag)
    {
        CMD_EXEC("wpa_cli -i%s p2p_set go_apsd %d",getStaSetP2p->intf, getStaSetP2p->go_apsd );
    }

    if (getStaSetP2p->discover_type_flag)
    {
        DPRINT_INFO("NOT CONFIGURABLE ON DUT   getStaSetP2p->discoverType\r\n");
    }

    if (getStaSetP2p->p2p_mode_flag)
    {
        CMD_EXEC("wpa_cli -i%s p2p_stop_find",getStaSetP2p->intf);

        if(os_strcasecmp(getStaSetP2p->p2p_mode, "discover") == 0)
        {
            CMD_EXEC("wpa_cli -i%s p2p_find",getStaSetP2p->intf);
        }
        else if (os_strcasecmp(getStaSetP2p->p2p_mode, "Listen") == 0)
        {
            CMD_EXEC("wpa_cli -i%s p2p_listen 90",getStaSetP2p->intf);
        }
        else if (os_strcasecmp(getStaSetP2p->p2p_mode, "Idle") == 0)
        {
            CMD_EXEC("wpa_cli -i%s p2p_stop_find",getStaSetP2p->intf);
        }
        else
        {
            CMD_EXEC("wpa_cli -i%s p2p_find",getStaSetP2p->intf);
        }
    }
//   }
//   else
//   {
//      wSLEEP(3);
//      DPRINT_INFO("-->Command = %s\r\n",inv_connect_req);
//      if ((sys_err = system(inv_connect_req))==-1){return WFA_FAILURE;}
//      Store_Inv_Req=0;
//      memset(inv_connect_req, 0, 100);
//  }

    infoResp->status = STATUS_COMPLETE;
    WFA_ENC_TLV(WFA_STA_P2P_SETP2P_TLV, sizeof(infoResp), (BYTE *)&infoResp, respBuf);
    *respLen = WFA_TLV_HDR_LEN + sizeof(infoResp);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

/*
 * wfaStaP2pConnect():
 */
int wfaStaP2pConnect(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
    dutCmdResponse_t *infoResp  = &gGenericResp;
    caStaP2pConnect_t *getStaP2pConnect = (caStaP2pConnect_t *)caCmdBuf;
    int P2P_Discovered = 0;

    DPRINT_IN_FUNC();

    P2P_Discovered=IsDiscovered(getStaP2pConnect->intf,getStaP2pConnect->devId);

    if ( P2P_Discovered == 1)
    {
        if (WPSConfig.wps_pbc_flag)
        {
            CMD_EXEC("wpa_cli -i%s p2p_connect %s pbc join",getStaP2pConnect->intf,getStaP2pConnect->devId);
        }
        else if(WPSConfig.wps_pin_flag)
        {
            CMD_EXEC("wpa_cli -i%s p2p_connect %s %s join ",getStaP2pConnect->intf, getStaP2pConnect->devId,WPSPin);
        }
        else
            DPRINT_ERR("ERROR in WPS Provisioning \r\n");
        infoResp->status = STATUS_COMPLETE;
    }
    else
       infoResp->status = STATUS_ERROR;

    //Waiting for association
    wSLEEP(20);

    WFA_ENC_TLV(WFA_STA_P2P_CONNECT_TLV, sizeof(dutCmdResponse_t), (BYTE *)infoResp, respBuf);
    *respLen = WFA_TLV_HDR_LEN + sizeof(dutCmdResponse_t);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

/*
 * wfaStaStartAutoGo():
 */
int wfaStaStartAutoGo(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
    char string[64];
    char *string1=" ";
    caStaStartAutoGo_t *autoGoparams = (caStaStartAutoGo_t *)caCmdBuf;
    char *str;
    FILE *tmpfd;
    dutCmdResponse_t *autogoResp = &gGenericResp;
    char ssid[WFA_SSID_NAME_LEN];
    char devid[64];

    DPRINT_IN_FUNC();

    CMD_EXEC("pkill dhclient");
    wSLEEP(5);

    DPRINT_BOX("Init IP address ..." );
    CMD_EXEC("ifconfig %s 192.168.251.%d ",autoGoparams->intf, DUT_IP_IDX);
    CMD_EXEC("cp /valid/dhcp_conf_file/dhcpd.conf /etc/dhcp/dhcpd.conf");
    CMD_EXEC("sudo systemctl restart dhcpd.service");
    wSLEEP(10);

    if (autoGoparams->ssid_flag)
    {
        CMD_EXEC("wpa_cli -i %s p2p_set ssid_postfix %s",autoGoparams->intf, autoGoparams->ssid );
    }

    if (autoGoparams->rtsp_flag)
    {
        DPRINT_INFO("--> Do nothing");
    }

    CMD_EXEC("wpa_cli -i %s p2p_group_add freq=%d",autoGoparams->intf, wfa_channel_val[autoGoparams->oper_chn] );
    CMD_EXEC("wpa_cli -i %s status > /valid/tmp/status_file.txt",autoGoparams->intf );
    tmpfd = fopen("/valid/tmp/status_file.txt", "r+");

    if(tmpfd == NULL)
    {
        autogoResp->status = STATUS_ERROR;
        WFA_ENC_TLV(WFA_STA_P2P_START_AUTO_GO_TLV, 4, (BYTE *)autogoResp, respBuf);
        *respLen = WFA_TLV_HDR_LEN + 4;

        DPRINT_ERR("/valid/tmp/status_file.txt file open failed\r\n");
        return WFA_FAILURE;
    }

    for(;;)
    {
        if(fscanf(tmpfd, "%63s", string) == EOF)
        {
            autogoResp->status = STATUS_COMPLETE;
            strcpy(autogoResp->cmdru.grpid, "00:00:00:00:00:00   XXX");
            break;
        }

        if(strncmp(string, "ssid", 4) == 0)
        {
            str = strtok(string, "=");
            str = strtok(NULL, "=");
            if(str != NULL)
            {
                strcpy(ssid, str);
            }
        }

        if(strncmp(string, "p2p_device_address", 18) == 0)
        {
            str = strtok(string, "=");
            str = strtok(NULL, "=");
            if(str != NULL)
            {
                strcpy(devid, str);
                autogoResp->status = STATUS_COMPLETE;
            }

            strcat(devid, string1);
            strcat(devid,ssid);
            //DPRINT_INFO("-->devid = %s\r\n",devid);

            strcpy(autogoResp->cmdru.grpid,devid);
            DPRINT_INFO("--> grpid = %s\r\n",autogoResp->cmdru.grpid);
            autogoResp->status = STATUS_COMPLETE;
            break;
        }
    }

    WFA_ENC_TLV(WFA_STA_P2P_START_AUTO_GO_TLV, sizeof(dutCmdResponse_t), (BYTE *)autogoResp, respBuf);
    *respLen = WFA_TLV_HDR_LEN + sizeof(dutCmdResponse_t);

    fclose(tmpfd);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

int IsDiscovered(char * interface, char * devID)
{
    int P2P_Discovered = 0, iter=0;
    FILE *tmpfd;
    char string[64];

    DPRINT_IN_FUNC();

    DPRINT_BOX("Check P2P Discovered ..." );

    //TEST before find
    CMD_EXEC("wpa_cli -i%s p2p_peer %s > /valid/tmp/discovered.txt",interface,devID);

    tmpfd = fopen("/valid/tmp/discovered.txt", "r+");
    if(tmpfd == NULL)
    {
        DPRINT_ERR("/valid/tmp/discovered.txt : Error while opening file\r\n");
        return WFA_FAILURE;
    }

    if((fscanf(tmpfd, "%63s", string) != EOF) && (os_strcasecmp(string, "FAIL") != 0))
    {
        P2P_Discovered = 1;
    }
    fclose(tmpfd);
    tmpfd = NULL;

    while ((P2P_Discovered == 0) && (iter < 5))
    {
        DPRINT_INFO("--> devId = %s \r\n", devID);
        CMD_EXEC("wpa_cli -i%s p2p_find ",interface);

        wSLEEP(5);

        CMD_EXEC("wpa_cli -i%s p2p_stop_find",interface);
        CMD_EXEC("wpa_cli -i%s p2p_peer %s > /valid/tmp/discovered.txt",interface,devID);

        tmpfd = fopen("/valid/tmp/discovered.txt", "r+");
        if(tmpfd == NULL)
        {
            DPRINT_ERR("/valid/tmp/discovered.txt : Error while opening file\r\n");
            return WFA_FAILURE;
        }

        if(fscanf(tmpfd, "%63s", string) == EOF)
        {
            DPRINT_ERR("cannot connect to %s : not discovered\r\n",devID );
            fclose(tmpfd);
            break;
        }

        P2P_Discovered = 1;
        fclose(tmpfd);
        tmpfd = NULL;
        break;
        DPRINT_CONTENT_S("\r\n**********************************************************\r\n");
        //if(strncmp(string,devID,2) == 0)
        //{
        //  P2P_Discovered = 1;
        //  break;
        //}
        iter ++;
   }

    DPRINT_OUT_FUNC();

    return P2P_Discovered;
}

int IsRuning_dhcp(void)
{
    char stringr[64];
    FILE *tmpfdr;
    int isRuning = 0;

    DPRINT_IN_FUNC();

    DPRINT_BOX("Check Server DHCP ..." );
    CMD_EXEC("ps ax | grep -i -c dhc > /valid/tmp/dhc.txt");

    tmpfdr = fopen("/valid/tmp/dhc.txt", "r+");
    if(tmpfdr == NULL)
    {
        DPRINT_INFO("Error while opening file\r\n");
        return WFA_FAILURE;
    }

    if(fscanf(tmpfdr, "%63s", stringr) == EOF)
    {
        DPRINT_ERR("IsRuning_dhcp\r\n");
        isRuning = 0;
    }
    else
    {
        isRuning = atoi(stringr);
    }
    fclose (tmpfdr);
    DPRINT_CONTENT_S("\r\n**********************************************************\r\n");

    DPRINT_OUT_FUNC();

    return isRuning;
}

int dhcp_configuration(int DeviceMode, char * interface)
{
    DPRINT_IN_FUNC();

    /*int dhcpIsRuning=0;

    dhcpIsRuning = IsRuning_dhcp();
    if (dhcpIsRuning > 0)
    {
        CMD_EXEC("pkill -f dhc");
        wSLEEP(2);
    }
     */

    if (DeviceMode == 1) //CLIENT
    {
        DPRINT_BOX("Stop Server DHCP ..." );
        CMD_EXEC("sudo systemctl stop dhcpd.service");
        wSLEEP(5);

        DPRINT_BOX("Start Server DHCP ..." );
        CMD_EXEC("dhclient %s -v", interface);
        wSLEEP(10);
    }
    else//GO
    {
        DPRINT_BOX("Stop Client DHCP ..." );
        CMD_EXEC("pkill dhclient");
        wSLEEP(5);

        DPRINT_BOX("Start Server DHCP ..." );
        CMD_EXEC("ifconfig %s 192.168.251.%d ",interface, DUT_IP_IDX);

        DPRINT_BOX("Copy DHCP server conf ..." );
        CMD_EXEC("cp /valid/dhcp_conf_file/dhcpd.conf /etc/dhcp/dhcpd.conf");

        DPRINT_BOX("Re-Start Server DHCP ..." );
        CMD_EXEC("sudo systemctl restart dhcpd.service");
        wSLEEP(10);
    }

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

/*
 * wfaStaP2pStartGrpFormation():
 */
int wfaStaP2pStartGrpFormation(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
    char string[64];
    char *string1=" ";
    caStaP2pStartGrpForm_t *StartGrpForm = (caStaP2pStartGrpForm_t *)caCmdBuf;
    dutCmdResponse_t *infoResp = &gGenericResp;
    caP2pStartGrpFormResp_t*StartGrpFormResp = &infoResp->cmdru.grpFormInfo;

    char *str;
    FILE *tmpfd;
    int P2P_Discovered = 0;
    char ssid[WFA_SSID_NAME_LEN];
    char devid[WFA_P2P_DEVID_LEN];
    char freq_str[10] = "freq=";
    char GoI[5] = "auth";
    char persistent[11] = "persistent";
    char freq[16];
    int DeviceMode=0;

    DPRINT_IN_FUNC();

    DPRINT_BOX("P2P Discovered...");
    P2P_Discovered=IsDiscovered(StartGrpForm->intf,StartGrpForm->devId);

    if( P2P_Discovered == 1)
    {
        if(persistent_val == 0)
        {
            DPRINT_INFO("--> In persistent_flag= %s\r\n",persistent);
            memset(persistent, 0, strlen(persistent));
        }


        if(StartGrpForm->ssid_flag)
        {
            CMD_EXEC("wpa_cli -i%s p2p_set ssid_postfix %s",StartGrpForm->intf, StartGrpForm->ssid);
        }

        if(StartGrpForm->oper_chn_flag)
        {
            DPRINT_INFO("--> In Freq_flag chan = %d\r\n",StartGrpForm->oper_chn);
            //freq = (char*)wfa_channel_val[StartGrpForm->oper_chn];
            sprintf(freq, "%d", wfa_channel_val[StartGrpForm->oper_chn]);
            //DPRINT_INFO("-->In Freq_flag=%s\r\n",freq);

            strcat(freq_str,freq);
            //DPRINT_INFO("-->In Freq_str=%s\r\n", freq_str);

            Old_Freq=wfa_channel_val[StartGrpForm->oper_chn];
            DPRINT_INFO("--> Store Freq=%d\r\n", Old_Freq);
        }
        else
        {
            DPRINT_INFO("--> freq_str should be null\r\n");
            memset(freq_str, 0, strlen(freq_str));
        }

        if(StartGrpForm->init_go_neg)
        {
            memset(GoI, 0, strlen(GoI));
        }

        if((WPSConfig.wps_pin_keypad_flag == 1) || (WPSConfig.wps_pin_label_flag == 1))
            CMD_EXEC("wpa_cli -i%s p2p_connect %s %s go_intent=%d %s %s %s",StartGrpForm->intf,StartGrpForm->devId, WPSPin, StartGrpForm->intent_val, freq_str,persistent,GoI);
        else if (WPSConfig.wps_pin_display_flag == 1)
            CMD_EXEC("wpa_cli -i%s p2p_connect %s %s display go_intent=%d %s %s %s",StartGrpForm->intf,StartGrpForm->devId, WPSPin, StartGrpForm->intent_val, freq_str,persistent,GoI);
        else
            CMD_EXEC("wpa_cli -i%s p2p_connect %s pbc go_intent=%d %s %s %s",StartGrpForm->intf,StartGrpForm->devId, StartGrpForm->intent_val, freq_str,persistent,GoI);

        if(StartGrpForm->init_go_neg)
        {
            wSLEEP(20);

            CMD_EXEC("wpa_cli -i%s status > /valid/tmp/status_file.txt",StartGrpForm->intf );
            tmpfd = fopen("/valid/tmp/status_file.txt", "r+");

            if(tmpfd == NULL)
            {
                infoResp->status = STATUS_ERROR;
                WFA_ENC_TLV(WFA_STA_P2P_START_GRP_FORMATION_TLV, 4, (BYTE *)infoResp, respBuf);
                *respLen = WFA_TLV_HDR_LEN + 4;

                DPRINT_ERR("file open failed");
                return WFA_FAILURE;
            }

            for(;;)
            {
                if(fscanf(tmpfd, "%63s", string) == EOF)
                {
                    infoResp->status = STATUS_COMPLETE;
                    strcpy(StartGrpFormResp->grpId, "00:00:00:00:00:00   XXX");
                    break;
                }

                if(strncmp(string, "wpa_state", 9) == 0)
                {
                    str = strtok(string, "=");
                    str = strtok(NULL, "=");
                    if(strncmp(str, "DISCONNECTED", 9) == 0)
                    {
                        strcpy(StartGrpFormResp->result,"FAIL");
                        strcpy(StartGrpFormResp->grpId, "00:00:00:00:00:00   XXX-XX");
                        infoResp->status = STATUS_COMPLETE;
                        break;
                    }
                }

                if(strncmp(string, "ssid", 4) == 0)
                {
                    str = strtok(string, "=");
                    str = strtok(NULL, "=");
                    if(str != NULL)
                    {
                        strcpy(ssid, str);
                        DPRINT_INFO("--> ssid= %s\r\n",ssid);
                    }
                    infoResp->status = STATUS_COMPLETE;
                }

                if(strncmp(string, "mode", 4) == 0)
                {
                    str = strtok(string, "=");
                    str = strtok(NULL, "=");
                    if(str != NULL)
                    {
                        DPRINT_INFO("--> mode = %s\r\n",str);

                        if(strncmp(str, "P2P", 3) == 0)
                        {
                            strcpy(StartGrpFormResp->result,"GO");
                            DeviceMode = 2;
                        }
                        else if(strncmp(str, "station", 7) == 0)
                        {
                            strcpy(StartGrpFormResp->result,"CLIENT");
                            DeviceMode = 1;
                        }
                        else
                            strcpy(StartGrpFormResp->result,"FAIL");

                    }
                    infoResp->status = STATUS_COMPLETE;
                }

                if(strncmp(string, "p2p_device_address", 18) == 0)
                {
                    str = strtok(string, "=");
                    str = strtok(NULL, "=");
                    if(str != NULL)
                    {
                        strcpy(devid, str);
                    }
                    strcat(devid, string1);
                    strcat(devid,ssid);
                    strcpy(StartGrpFormResp->grpId,devid);
                    DPRINT_INFO("--> result = %s  groupID = %s\r\n",StartGrpFormResp->result,StartGrpFormResp->grpId);
                    infoResp->status = STATUS_COMPLETE;
                    break;
                }
            }
            fclose(tmpfd);
        }
        else
        {
            strcpy(StartGrpFormResp->result,"Null");
            strcpy(StartGrpFormResp->grpId, "00:00:00:00:00:00 DIRECT-XX");
            infoResp->status = STATUS_COMPLETE;
            DPRINT_ERR("--> result = %s  groupID = %s\r\n",StartGrpFormResp->result,StartGrpFormResp->grpId);
        }
    }
    DPRINT_CONTENT_S("\r\n**********************************************************\r\n");

    DPRINT_BOX("DHCP Configuration ..." );
    dhcp_configuration(DeviceMode,StartGrpForm->intf);

    WFA_ENC_TLV(WFA_STA_P2P_START_GRP_FORMATION_TLV, sizeof(dutCmdResponse_t), (BYTE *)infoResp, respBuf);
    *respLen = WFA_TLV_HDR_LEN + sizeof(dutCmdResponse_t);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

/*
 * wfaStaP2pDissolve():
 */
int wfaStaP2pDissolve(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
    char string[64];
    caStaP2pDissolve_t *caStaP2pDissolve = (caStaP2pDissolve_t*) caCmdBuf;
    /*char *str;*/
    FILE *tmpfd;
    dutCmdResponse_t *dissolveResp = &gGenericResp;
    int modeGO = 0, modeCLI=0;

    DPRINT_IN_FUNC();

    CMD_EXEC("wpa_cli -i %s status | grep -i mode | cut -f2 -d= > /valid/tmp/status_file.txt",caStaP2pDissolve->intf );
    tmpfd = fopen("/valid/tmp/status_file.txt", "r+");

    if(tmpfd == NULL)
    {
        dissolveResp->status = STATUS_ERROR;
        WFA_ENC_TLV(WFA_STA_P2P_DISSOLVE_TLV, 4, (BYTE *)dissolveResp, respBuf);
        *respLen = WFA_TLV_HDR_LEN + 4;

        DPRINT_ERR("/valid/tmp/status_file.txt file open failed");
        return WFA_FAILURE;
    }

    fscanf(tmpfd, "%63s", (char *)string);

    if(strncmp(string, "P2P",3) == 0)
    {
        modeGO = 1;
        Old_DeviceMode = 2;
    }
    else if(strncmp(string, "station", 6) == 0)
    {
        modeCLI = 1;
        Old_DeviceMode = 1;
    }
    else
    {
        modeCLI = 1;
        Old_DeviceMode = Store_P2PDevice;
    }

    if ( modeGO == 1)
    {
        DPRINT_INFO("--> is GO: disconnect all Sta and remove group \r\n");
        CMD_EXEC("wpa_cli -i%s p2p_group_remove %s",caStaP2pDissolve->intf ,caStaP2pDissolve->intf );
        dissolveResp->status = STATUS_COMPLETE;
    }
    else if ( modeCLI == 1)
    {
        //DPRINT_INFO(" --> is CLIENT: disconnect from Group \r\n");
        //CMD_EXEC("wpa_cli -i%s disconnect ",caStaP2pDissolve->intf );
        DPRINT_INFO("--> is GO: disconnect all Sta and remove group \r\n");
        CMD_EXEC("wpa_cli -i%s p2p_group_remove %s",caStaP2pDissolve->intf ,caStaP2pDissolve->intf );
        dissolveResp->status = STATUS_COMPLETE;
    }
    else
    {
        DPRINT_INFO("--> IF is not CLIENT nor GROUP \r\n");
        DPRINT_INFO("--> GROUP has already been dissolved\r\n");
        dissolveResp->status = STATUS_COMPLETE;
    }

    WFA_ENC_TLV(WFA_STA_P2P_DISSOLVE_TLV, sizeof(dutCmdResponse_t), (BYTE *)dissolveResp, respBuf);
    *respLen = WFA_TLV_HDR_LEN + sizeof(dutCmdResponse_t);

    fclose(tmpfd);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}
/*
 * wfaStaSendP2pInvReq():
 */
int wfaStaSendP2pInvReq(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
    dutCmdResponse_t *infoResp = &gGenericResp;
    caStaSendP2pInvReq_t *getStaP2pInvReq= (caStaSendP2pInvReq_t *)caCmdBuf;
    FILE *tmpfd;
    char string[64] /*, *str*/;
    int nID /*,DeviceMode = 0*/;
    int P2P_Discovered = 0;

    DPRINT_IN_FUNC();

    //DeviceMode = IsGroupOwner(getStaP2pInvReq->intf);
    P2P_Discovered=IsDiscovered(getStaP2pInvReq->intf,getStaP2pInvReq->devId);
    if(P2P_Discovered == 1)
    {
        if (getStaP2pInvReq->reinvoke == 1)
        {
            CMD_EXEC("wpa_cli -i%s list_network | grep -i PERSISTENT > /valid/tmp/list_network.txt",getStaP2pInvReq->intf);
            tmpfd = fopen("/valid/tmp/list_network.txt", "r+");
            if (tmpfd == NULL)
                return WFA_FAILURE;

            if (!fscanf(tmpfd, "%63s", string))
            {
                fclose(tmpfd);
                return WFA_FAILURE;
            }
            nID = atoi(string);
            fclose(tmpfd);

            if(Old_DeviceMode == 1)
            {
                CMD_EXEC("wpa_cli -i%s p2p_invite persistent=%d peer=%s freq=%d",getStaP2pInvReq->intf,nID,getStaP2pInvReq->devId,Old_Freq );
            }
            else if (Old_DeviceMode == 2)
            {
                CMD_EXEC("wpa_cli -i%s p2p_group_add persistent=%d freq=%d",getStaP2pInvReq->intf,nID,Old_Freq );
                CMD_EXEC("wpa_cli -i%s p2p_invite persistent=%d peer=%s freq=%d",getStaP2pInvReq->intf,nID,getStaP2pInvReq->devId,Old_Freq );
            }
            else
                DPRINT_ERR("Old_DeviceMode = 0");

        }
        else
        {
            CMD_EXEC("wpa_cli -i%s p2p_invite group=%s peer=%s ",getStaP2pInvReq->intf,getStaP2pInvReq->intf,getStaP2pInvReq->devId );
        }
    }

    wSLEEP(15);
    infoResp->status = STATUS_COMPLETE;
    WFA_ENC_TLV(WFA_STA_P2P_SEND_INV_REQ_TLV, sizeof(infoResp), (BYTE *)&infoResp, respBuf);
    *respLen = WFA_TLV_HDR_LEN + sizeof(infoResp);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

/*
 * wfaStaAcceptP2pInvReq():
 */
int wfaStaAcceptP2pInvReq(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
    dutCmdResponse_t *infoResp = &gGenericResp;
    caStaAcceptP2pInvReq_t *getStaP2pInvReq= (caStaAcceptP2pInvReq_t *)caCmdBuf;
    int P2P_Discovered = 0;

    DPRINT_IN_FUNC();

    P2P_Discovered=IsDiscovered(getStaP2pInvReq->intf,getStaP2pInvReq->devId);
    if (getStaP2pInvReq->reinvoke==0)
    {
        if ( P2P_Discovered == 1)
        {
            if ((WPSConfig.wps_pin_keypad_flag == 1) || (WPSConfig.wps_pin_label_flag == 1))
                CMD_EXEC("wpa_cli -i %s p2p_connect %s %s auth join",getStaP2pInvReq->intf,getStaP2pInvReq->devId, WPSPin);
            else if (WPSConfig.wps_pin_display_flag == 1)
                CMD_EXEC("wpa_cli -i %s p2p_connect %s %s display auth join",getStaP2pInvReq->intf,getStaP2pInvReq->devId, WPSPin);
            else
                CMD_EXEC("wpa_cli -i %s p2p_connect %s pbc auth join",getStaP2pInvReq->intf,getStaP2pInvReq->devId);

            Store_Inv_Req=1;
        }
        //wSLEEP(5);
    }
    else
    {
        //CMD_EXEC("wpa_cli -i %s set p2p_oper_channel %d",getStaP2pInvReq->intf,Old_Freq);
        if ((WPSConfig.wps_pin_keypad_flag == 1) || (WPSConfig.wps_pin_label_flag == 1))
            CMD_EXEC("wpa_cli -i %s p2p_connect %s %s auth join persistent",getStaP2pInvReq->intf,getStaP2pInvReq->devId, WPSPin);
        else if (WPSConfig.wps_pin_display_flag == 1)
            CMD_EXEC("wpa_cli -i %s p2p_connect %s %s display auth join persistent",getStaP2pInvReq->intf,getStaP2pInvReq->devId, WPSPin);
        else
            CMD_EXEC("wpa_cli -i %s p2p_connect %s pbc auth join persistent",getStaP2pInvReq->intf,getStaP2pInvReq->devId);
        Store_Inv_Req=1;
    }

    CMD_EXEC("wpa_cli -i%s p2p_listen 90",getStaP2pInvReq->intf);

    infoResp->status = STATUS_COMPLETE;
    WFA_ENC_TLV(WFA_STA_P2P_ACCEPT_INV_REQ_TLV, sizeof(infoResp), (BYTE *)&infoResp, respBuf);
    *respLen = WFA_TLV_HDR_LEN + sizeof(infoResp);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}


