/*
 * wfaStaP2pReset():
 */

int wfaStaP2pReset(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
    dutCmdResponse_t *infoResp=&gGenericResp;
    dutCommand_t *getStaP2pReset= (dutCommand_t *)caCmdBuf;
    Store_Inv_Req=0;
    char *ifname = getStaP2pReset->intf;
    iteration ++;
    int dut_mode = 3;
    DPRINT_IN_FUNC();

    //#######################################################################################################################################
    //#############################################  LOAD RW DRIVER / START SUPPLICANT ######################################################
    //#######################################################################################################################################
    if (RestartDUT(ifname,dut_mode) == WFA_FAILURE)
        return WFA_FAILURE;

    //#######################################################################################################################################
    //#############################################  DHCP CONFIGURATION  ####################################################################
    //#######################################################################################################################################

    CMD_EXEC("pkill dhclient");
    wSLEEP(5);

    CMD_EXEC("sudo systemctl stop dhcpd.service");
    wSLEEP(10);

    CMD_EXEC("ps ax | grep -i -c dhc > /valid/tmp/dhc.txt");

    CMD_EXEC("wpa_cli -i%s remove_network all ",getStaP2pReset->intf);
    sleep(2);

    persistent_flag = 0;
    Old_DeviceMode = 0;
    infoResp->status = STATUS_COMPLETE;
    WFA_ENC_TLV(WFA_STA_P2P_RESET_TLV, sizeof(dutCmdResponse_t), (BYTE *)infoResp, respBuf);
    *respLen = WFA_TLV_HDR_LEN + sizeof(dutCmdResponse_t);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}
/*
 * wfaStaGetP2pIpConfig():
 */
int wfaStaGetP2pIpConfig(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
    dutCmdResponse_t *infoResp = &gGenericResp;
    caStaGetP2pIpConfig_t *staGetP2pIpConfig= (caStaGetP2pIpConfig_t *)caCmdBuf;
    caStaGetIpConfigResp_t *ifinfo = &(infoResp->cmdru.getIfconfig);
    FILE *tmpfd;
    char string[256];
    char *str;
    int slen,i=0;
    int DeviceMode=0;

    DPRINT_IN_FUNC();

    DeviceMode = IsGroupOwner(staGetP2pIpConfig->intf);
    i = dhcp_configuration(DeviceMode,staGetP2pIpConfig->intf);

    //Fetch the device IP config  and put in    infoResp->cmdru
    //strcpy(infoResp->cmdru.wpsPin, "12345678");
    //ifinfo->isDhcp =0;
    //strcpy(&(ifinfo->ipaddr[0]), "192.165.100.111");
    //strcpy(&(ifinfo->mask[0]), "255.255.255.0");
    //strcpy(&(ifinfo->dns[0][0]), "192.165.100.1");
    //strcpy(&(ifinfo->mac[0]), "ba:ba:ba:ba:ba:ba");

#ifdef XXX
    ret = access("/valid/bin/getipconfig.sh", F_OK);
    if(ret == -1)
    {
        infoResp->status = STATUS_ERROR;
        WFA_ENC_TLV(WFA_STA_P2P_GET_IP_CONFIG_TLV, 4, (BYTE *)infoResp, respBuf);
        *respLen = WFA_TLV_HDR_LEN + 4;

        DPRINT_ERR("getipconfig.sh file does not exist");
        return WFA_FAILURE;

    }
#endif

    strcpy(ifinfo->dns[0], "0");
    strcpy(ifinfo->dns[1], "0");

    /*
     * Run the script file "getipconfig.sh" to check the ip status
     * (current implementation  specific).
     * note: "getipconfig.sh" is only defined for the current implementation
     */
    CMD_EXEC("/valid/bin/getipconfig.sh /valid/tmp/ipconfig.txt %s\n", staGetP2pIpConfig->intf);

    /* open the output result and scan/retrieve the info */
    tmpfd = fopen("/valid/tmp/ipconfig.txt", "r+");

    if(tmpfd == NULL)
    {
        infoResp->status = STATUS_ERROR;
        WFA_ENC_TLV(WFA_STA_P2P_GET_IP_CONFIG_TLV, 4, (BYTE *)infoResp, respBuf);
        *respLen = WFA_TLV_HDR_LEN + 4;

        DPRINT_ERR("ipconfig.txt file does not exist");
        return WFA_FAILURE;
    }

    for(;;)
    {
        if(fgets(string, 256, tmpfd) == NULL)
            break;

        /* find out the mac address */
        if(strncmp(string, "mac", 3) == 0)
        {
            DPRINT_INFO("--> Find out the mac address \r\n");

            str = strtok(string, "=");
            str = strtok(NULL, " ");
            if(str != NULL)
            {
                wSTRNCPY(ifinfo->mac, str, WFA_MAC_ADDR_STR_LEN);
            }
            else
                wSTRNCPY(ifinfo->mac, "none", WFA_MAC_ADDR_STR_LEN);
        }


        /* check dhcp enabled */
        if(strncmp(string, "dhcpcli", 7) ==0)
        {
            DPRINT_INFO("--> Check dhcp enabled \r\n");

            str = strtok(string, "=");
            str = strtok(NULL, "=");
            DPRINT_INFO("--> dhcpcli= %s \r\n",str);

            if(str != NULL)
                ifinfo->isDhcp = 1;
            else
                ifinfo->isDhcp = 0;
        }

        /* find out the ip address */
        if(strncmp(string, "ipaddr", 6) == 0)
        {
            DPRINT_INFO("--> Find out the ip address \r\n");

            str = strtok(string, "=");
            str = strtok(NULL, " ");
            if(str != NULL)
            {
                wSTRNCPY(ifinfo->ipaddr, str, WFA_IP_ADDR_STR_LEN);
                ifinfo->ipaddr[15]='\0';
            }
            else
                wSTRNCPY(ifinfo->ipaddr, "none", WFA_IP_ADDR_STR_LEN);
        }

        /* check the mask */
        if(strncmp(string, "mask", 4) == 0)
        {
            DPRINT_INFO("--> Check the mask \r\n");
            char ttstr[16];
            char *ttp = ttstr;

            str = strtok_r(string, "=", &ttp);
            if(*ttp != '\0')
            {
                strcpy(ifinfo->mask, ttp);
                slen = strlen(ifinfo->mask);
                ifinfo->mask[slen-1] = '\0';
            }
            else
                strcpy(ifinfo->mask, "none");
        }

        /* find out the dns server ip address */
        if(strncmp(string, "nameserv", 8) == 0)
        {
            DPRINT_INFO("--> Find out the dns server ip address \r\n");
            char ttstr[16];
            char *ttp = ttstr;

            str = strtok_r(string, " ", &ttp);
            if(str != NULL && i < 2)
            {
                strcpy(ifinfo->dns[i], ttp);
                slen = strlen(ifinfo->dns[i]);
                ifinfo->dns[i][slen-1] = '\0';
            }
            else
                strcpy(ifinfo->dns[i], "none");
            i++;
        }
    }

    infoResp->status = STATUS_COMPLETE;
    WFA_ENC_TLV(WFA_STA_P2P_GET_IP_CONFIG_TLV, sizeof(dutCmdResponse_t), (BYTE *)infoResp, respBuf);
    *respLen = WFA_TLV_HDR_LEN + sizeof(dutCmdResponse_t);
    fclose(tmpfd);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}


