int IsGroupOwner( char * interface)
{
    FILE *tmpfd=NULL;
    int P2PDevice=0;
    char string[64];

    DPRINT_IN_FUNC();

    CMD_EXEC("wpa_cli -i %s status | grep -i mode | cut -f2 -d= > /valid/tmp/status_file.txt",interface );
    tmpfd = fopen("/valid/tmp/status_file.txt", "r+");

    if(tmpfd == NULL)
    {
        return WFA_FAILURE;
    }

    fscanf(tmpfd, "%63s", (char *)string);

    if(strncmp(string, "P2P", 3) == 0)
    {
        P2PDevice = 2; //Group Owner
        Store_P2PDevice = 2;
        DPRINT_INFO("--> Mode = %s \r\n", string);
    }
    else if(strncmp(string, "station", 6) == 0)
    {
        P2PDevice = 1; //client
        Store_P2PDevice = 1;
        DPRINT_INFO("--> Mode = %s \r\n", string);
    }
    else
    {
        DPRINT_ERR("--> Mode not define, default Client mode");
        P2PDevice = 1; // not define, default Client mode
        Store_P2PDevice = 1;
    }

    fclose(tmpfd);

    DPRINT_OUT_FUNC();

    return P2PDevice;
}

/*
 * wfaStaWpsReadPin():
 */
int wfaStaWpsReadPin(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
    dutCmdResponse_t *infoResp = &gGenericResp;
    caStaWpsReadPin_t *getStaWpsReadPin= (caStaWpsReadPin_t *)caCmdBuf;
    FILE *tmpfd=NULL;
    char result[WFA_WPS_PIN_LEN];
    int DeviceMode=0;

    DPRINT_IN_FUNC();

    DeviceMode = IsGroupOwner(getStaWpsReadPin->intf);

    if (DeviceMode == 2)
    {
        CMD_EXEC("wpa_cli -i%s wps_pin any >/valid/tmp/wpspin.txt",getStaWpsReadPin->intf);
    }
    else
    {
        CMD_EXEC("wpa_cli -i %s wps_pin get  >/valid/tmp/wpspin.txt",getStaWpsReadPin->intf);
    }

    tmpfd = fopen("/valid/tmp/wpspin.txt", "r+");
    infoResp->status = STATUS_COMPLETE;

    if(tmpfd == NULL)
    {
        infoResp->status = STATUS_ERROR;
        WFA_ENC_TLV(WFA_STA_WPS_READ_PIN_TLV, 4, (BYTE *)infoResp, respBuf);
        *respLen = WFA_TLV_HDR_LEN + 4;
        DPRINT_ERR("/valid/tmp/wpspin.txt file open failed\r\n");
        return WFA_FAILURE;
    }
    sret = fscanf(tmpfd, "%255s", (char *)result);
    strcpy(infoResp->cmdru.wpsPin, (char *)result);
    strcpy( WPSPin, (char *)result);

    WFA_ENC_TLV(WFA_STA_WPS_READ_PIN_TLV, sizeof(dutCmdResponse_t), (BYTE *)infoResp, respBuf);
    *respLen = WFA_TLV_HDR_LEN + sizeof(dutCmdResponse_t);
    fclose(tmpfd);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

