/*
 * wfaStaGetPsk():
 */
int wfaStaGetPsk(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
    dutCmdResponse_t *infoResp = &gGenericResp;
    caP2pStaGetPskResp_t *P2pStaGetPskResp = &infoResp->cmdru.pskInfo;
    caStaGetPsk_t *getStaGetPsk= (caStaGetPsk_t *)caCmdBuf;
    char *str, string[64];
    FILE *tmpfd;

    DPRINT_IN_FUNC();

    //access("/usr/local/sbin/getpassphrase.sh", F_OK);
    strcpy(P2pStaGetPskResp->passPhrase, "1234456");
    strcpy(P2pStaGetPskResp->ssid, "WIFI_DIRECT");
    CMD_EXEC("/valid/bin/getpassphrase.sh /valid/tmp/passphrase.txt %s\n", getStaGetPsk->intf);

    tmpfd = fopen("/valid/tmp/passphrase.txt", "r+");

    if(tmpfd == NULL)
    {
      infoResp->status = STATUS_ERROR;
      WFA_ENC_TLV(WFA_STA_WPS_READ_PIN_TLV, 4, (BYTE *)infoResp, respBuf);
      *respLen = WFA_TLV_HDR_LEN + 4;
      DPRINT_ERR("/valid/tmp/passphrase.txt file open failed\r\n");
      return WFA_FAILURE;
    }

    for(;;)
    {
        if(fscanf(tmpfd, "%63s", string) == EOF)
        {
         infoResp->status = STATUS_COMPLETE;
         break;
        }
        else
        {
            if(strncmp(string, "mdp", 3) == 0)
            {
                str = strtok(string, "=");
                str = strtok(NULL, "=");
                if(str != NULL)
                {
                    strcpy(P2pStaGetPskResp->passPhrase,str);
                    infoResp->status = STATUS_COMPLETE;
                }
            }
            if(strncmp(string, "ssid", 4) == 0)
            {
                str = strtok(string, "=");
                str = strtok(NULL, "=");
                if(str != NULL)
                {
                    strcpy(P2pStaGetPskResp->ssid,str);
                    infoResp->status = STATUS_COMPLETE;
                    break;
                }
            }
        }
    }
    DPRINT_INFO("--> passphrase = %s\r\n",P2pStaGetPskResp->passPhrase);
    DPRINT_INFO("--> ssid = %s\r\n", P2pStaGetPskResp->ssid);

    infoResp->status = STATUS_COMPLETE;
    WFA_ENC_TLV(WFA_STA_P2P_GET_PSK_TLV, sizeof(dutCmdResponse_t), (BYTE *)infoResp, respBuf);
    *respLen = WFA_TLV_HDR_LEN + sizeof(dutCmdResponse_t);
    fclose(tmpfd);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

/*
 * wfaStaSendServiceDiscoveryReq():
 */
int wfaStaSendServiceDiscoveryReq(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
   dutCmdResponse_t *infoResp = &gGenericResp;
   caStaSendServiceDiscoveryReq_t *SendServiceDiscoveryReq = (caStaSendServiceDiscoveryReq_t *)caCmdBuf;

   DPRINT_IN_FUNC();

   CMD_EXEC("wpa_cli -i%s p2p_find %s ",SendServiceDiscoveryReq->intf,SendServiceDiscoveryReq->devId);
   CMD_EXEC("wpa_cli -i%s p2p_peer %s ",SendServiceDiscoveryReq->intf,SendServiceDiscoveryReq->devId);

   wSLEEP(5);

   CMD_EXEC("wpa_cli -i%s p2p_serv_disc_req %s 02000001",SendServiceDiscoveryReq->intf,SendServiceDiscoveryReq->devId);

   infoResp->status = STATUS_COMPLETE;
   WFA_ENC_TLV(WFA_STA_P2P_SEND_SERVICE_DISCOVERY_REQ_TLV, sizeof(infoResp), (BYTE *)&infoResp, respBuf);
   *respLen = WFA_TLV_HDR_LEN + sizeof(infoResp);

   DPRINT_OUT_FUNC();

   return WFA_SUCCESS;
}

