/*
 * wfaStaSetRFeature():
 */
int wfaStaSetRFeature(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
    dutCommand_t *dutCmd = (dutCommand_t *)caCmdBuf;
    caStaRFeat_t *rfeat = &dutCmd->cmdsu.rfeat;
    dutCmdResponse_t *caResp = &gGenericResp;
    //char *intf = dutCmd->intf;

    DPRINT_IN_FUNC();

    if(os_strcasecmp(rfeat->prog, "tdls") == 0)
    {
        DPRINT_INFO("PROG--> TDLS  \r\n");
        if(os_strcasecmp(rfeat->ChSwitchMode, "Initiate") == 0)
        {
            DPRINT_INFO("CHSWITCHMODE--> Initiate  \r\n");
            /* use the peer mac address to send the frame */
            CMD_EXEC("wpa_cli -i %s tdls_chan_switch %s 1 %d sec_channel_offset=%s", dutCmd->intf, rfeat->peer, rfeat->OffChFreq, rfeat->sec_channel_offset);
        }
        else if(os_strcasecmp(rfeat->ChSwitchMode, "Passive") == 0)
        {
            DPRINT_INFO("CHSWITCHMODE--> Passive  \r\n");
            /* use the peer mac address to send the frame */
            CMD_EXEC("wpa_cli -i %s tdls_cancel_chan_switch %s", dutCmd->intf, rfeat->peer);
        }
    }
    else if(os_strcasecmp(rfeat->prog, "mbo") == 0)
    {
        DPRINT_INFO("PROG--> MBO  \r\n");

        if (rfeat->Cellular_Data_Cap != 0)
        {
            DPRINT_INFO("MBO --> Trigger STAUT to disable/enable cellular data connection  \r\n");
            //CMD_EXEC("wpa_cli -i %s set mbo_cell_capa %d", dutCmd->intf, rfeat->Cellular_Data_Cap);
            cmd_wlan_sta_exec("set mbo_cell_capa %d ", rfeat->Cellular_Data_Cap);
        }

        if(rfeat->Ch_Pref_flag==1){
            DPRINT_INFO("MBO --> Configure non-preferred channels\r\n");
            if (rfeat->Ch_Pref != 3)
            {
                /* use op_class:ch_num:ch_pref:reason */
                //CMD_EXEC("wpa_cli -i %s set non_pref_chan %d:%d:%d:%d %d:%d:%d:%d ", dutCmd->intf, rfeat->Ch_Op_Class, rfeat->Ch_Pref_Num, rfeat->Ch_Pref, rfeat->Ch_Reason_Code);
                cmd_wlan_sta_exec("set non_pref_chan %d:%d:%d:%d  %d:%d:%d:%d",
                                   Ch_Op_Class1, Ch_Pref_Num1, Ch_Pref1, Ch_Reason_Code1,
                                   Ch_Op_Class2, Ch_Pref_Num2, Ch_Pref2, Ch_Reason_Code2);

            }else{
                //CMD_EXEC("wpa_cli -i %s set non_pref_chan", dutCmd->intf);
                cmd_wlan_sta_exec("set non_pref_chan");

            }
        }

    }
    else if(os_strcasecmp(rfeat->prog, "HE") == 0)
    {
        //APPLY FIXED RATE
        if (rfeat->mcs_fixedrate_id != 0){
            DPRINT_INFO("FIXED MCS --> %d  \r\n",rfeat->mcs_fixedrate_id);
#ifdef __LINUX__
            CMD_EXEC("echo %d > /sys/kernel/debug/ieee80211/phy0/rwnx/stations/%s/rc/fixed_rate_idx",rfeat->mcs_fixedrate_id, bssid);
            wSLEEP(3);
#else
            void *sta = sta_mgmt_get_sta(bssid_bin);
            os_printf("%s %d: %pm\n", __func__, __LINE__, bssid_bin);
            if (sta) {
#if 0
                union rwnx_rate_ctrl_info rate_config;

                /* Convert rate index into rate configuration */
                if ((rfeat->mcs_fixedrate_id < 0) || (rfeat->mcs_fixedrate_id >= (N_CCK + N_OFDM + N_HT + N_VHT + N_HE_SU)))
                {
                    // disable fixed rate
                    rate_config.value = (u32)-1;
                }
                else
                {
                    idx_to_rate_cfg(rfeat->mcs_fixedrate_id, &rate_config, NULL);
                }

                os_printf("%s %d: fixed rate 0x%x\n", __func__, __LINE__, rate_config.value);
                rw_send_me_rc_set_rate(mac_sta_mgmt_get_staid(sta), rate_config.value);
#else
                rw_send_me_rc_set_rate(mac_sta_mgmt_get_staid(sta), rfeat->mcs_fixedrate_id);
#endif
            }
#endif
        }

        if(rfeat->twt.on)
        {
            //char buf[750];
            //int len = 0;

            if (os_strcasecmp(rfeat->twt.setup, "teardown") != 0)
            {
                #if 0
                len += sprintf(buf + len, "setup_command = %d,", rfeat->twt.setup_command);
                len += sprintf(buf + len, "flow_type = %d,", rfeat->twt.flow_type);
                len += sprintf(buf + len, "wake_interval_mantissa = %d,", rfeat->twt.wake_interval_mantissa);
                len += sprintf(buf + len, "wake_interval_exp = %d,", rfeat->twt.wake_interval_exp);
                len += sprintf(buf + len, "nominal_min_wake_dur = %d,", rfeat->twt.nominal_min_wake_dur);
                len += sprintf(buf + len, "wake_dur_unit = %d", rfeat->twt.wake_dur_unit);

                sprintf(gCmdStr, "echo %s > /sys/kernel/debug/ieee80211/phy0/rwnx/stations/%s/twt/request", buf, bssid);
                CMD_EXEC(gCmdStr, "echo %s > /sys/kernel/debug/ieee80211/phy0/rwnx/stations/%s/twt/request", buf, bssid);
                #endif

                int ret = 0;
                struct twt_conf_tag twt_conf = {0};
                twt_conf.flow_type = rfeat->twt.flow_type;
                twt_conf.wake_int_exp = rfeat->twt.wake_interval_exp;
                twt_conf.wake_dur_unit = rfeat->twt.wake_dur_unit;
                twt_conf.wake_int_mantissa = rfeat->twt.wake_interval_mantissa;
                twt_conf.min_twt_wake_dur = rfeat->twt.nominal_min_wake_dur;
                extern int rwnx_msg_send_wfa_twt_setup(uint8_t setup_type, struct twt_conf_tag *twt_conf);
                ret = rwnx_msg_send_wfa_twt_setup(rfeat->twt.setup_command, &twt_conf);
                if (!ret) {
                    bk_printf("twt setup success\r\n");
                } else {
                    bk_printf("twt setup faile, ret = %d\r\n", ret);
                }

            }
            else
            {
                #if 0
                len += sprintf(buf, "flow_id = %d", rfeat->twt.flow_id);
                sprintf(gCmdStr, "echo %s > /sys/kernel/debug/ieee80211/phy0/rwnx/stations/%s/twt/teardown", buf, bssid);
                CMD_EXEC(gCmdStr, "echo %s > /sys/kernel/debug/ieee80211/phy0/rwnx/stations/%s/twt/teardown", buf, bssid);
                #endif
                unsigned char vif_idx = wifi_netif_mac_to_vifid((uint8_t*)&g_sta_param_ptr->own_mac);
                int ret = 0;
                ret = rw_msg_send_twt_teardown(vif_idx, rfeat->twt.flow_id);
                if (!ret)
                    bk_printf( "tear down success\r\n");
                else
                    bk_printf( "tear down fail, ret = %d\r\n", ret);
            }

            wSLEEP(3);
        }
    }

    caResp->status = STATUS_COMPLETE;
    WFA_ENC_TLV(WFA_STA_SET_RFEATURE_TLV, 4, (BYTE *)caResp, respBuf);
    *respLen = WFA_TLV_HDR_LEN + 4;

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

/* sendTCP()
 * this function is to generate TCP traffic.
 * it uses iperf to generate the traffic
 * store the result in TCP_file.txt
 * analyse the results and send it back
 */
int wfaStaSendTCP(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
    dutCmdResponse_t *SendTCPResp = &gGenericResp;
    SendTCP_t *SendTCP = (SendTCP_t *)caCmdBuf;

    DPRINT_IN_FUNC();

    CMD_EXEC("iperf -c %s -P %d -t %d -p %d &", SendTCP->dipaddr, SendTCP->NumStream, SendTCP->duration, SendTCP->port);

    SendTCPResp->status = STATUS_COMPLETE;
    WFA_ENC_TLV(WFA_STA_SENDTCP_TLV, 4, (BYTE *)SendTCPResp, respBuf);
    *respLen = WFA_TLV_HDR_LEN + 4;

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

/* wfaStopRcvTCP
 * This function is to put the station in receiver mode for iperf TCP traffic
 */
int wfaStaRcvTCP(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
    dutCmdResponse_t *RcvTCPResp = &gGenericResp;

    DPRINT_IN_FUNC();

    int *port = (int *)caCmdBuf;
    DPRINT_INFO("port = %d ...\r\n", *port);

    CMD_EXEC("iperf -s -f 'm' -p %d | grep -i MBytes > /valid/tmp/TCPFile.txt &",*port);

    RcvTCPResp->status = STATUS_COMPLETE;
    WFA_ENC_TLV(WFA_STA_RCVTCP_TLV, 4, (BYTE *)RcvTCPResp, respBuf);
    *respLen = WFA_TLV_HDR_LEN + 4;

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

