int wfaStaGetParameter(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
   dutCmdResponse_t *infoResp = &gGenericResp;
   caStaGetParameter_t *staGetParam= (caStaGetParameter_t *)caCmdBuf; //uncomment and use it
   caStaGetParameterResp_t *paramList = &infoResp->cmdru.getParamValue;
   int ret = WFA_SUCCESS;

   DPRINT_IN_FUNC();

   // Check the program type
   if(staGetParam->program == PROG_TYPE_WFD)
   {
      if(staGetParam->getParamValue == eDiscoveredDevList )
      {
          // Get the discovered devices, make space seperated list and return, check list is not bigger than 128 bytes.
          paramList->getParamType = eDiscoveredDevList;
          strcpy((char *)&paramList->devList, "11:22:33:44:55:66 22:33:44:55:66:77 33:44:55:66:77:88");
      }
      infoResp->status = STATUS_COMPLETE;
   }
   else if(staGetParam->program == PROG_TYPE_HE)
   {
        if (staGetParam->getParamValue == eRssi) {
            //FILE *tmpfd;
            int rssi = 0;

            paramList->getParamType = eRssi;

#ifdef __LINUX__
            /* retrieve the RSSI */
            CMD_EXEC("cat /sys/kernel/debug/ieee80211/phy*/rwnx/stations/%s/rc/rx_rate | tail -n 1 | grep -oE '[^ ]+$' > /valid/tmp/rssi.txt", bssid);
            tmpfd = fopen("/valid/tmp/rssi.txt", "r+");

            if (tmpfd == NULL) {
                infoResp->status = STATUS_ERROR;
                sprintf(paramList->devList, "%d", -40);
                DPRINT_ERR("Error: file open failed\r\n");
                ret = WFA_FAILURE;
                goto send_cfm;
            }

            infoResp->status = STATUS_COMPLETE;

            if (fscanf(tmpfd, "%d", &rssi) == EOF)
                sprintf(paramList->devList, "%d", -40);
            else
                sprintf(paramList->devList, "%d", rssi);
            fclose(tmpfd);
#else
            // struct rwnx_hw *rwnx_hw = &g_rwnx_hw;
            bool rssi_valid = false;

            uint8_t vif_idx = rwm_mgmt_vif_mac2idx((void *)&g_sta_param_ptr->own_mac);
            if (vif_idx != INVALID_VIF_IDX) {
                struct me_get_bss_info_cfm cfm;
                int val = rw_msg_get_bss_info(vif_idx, &cfm);
                if (!val) {
                    rssi = cfm.rssi;
                    rssi_valid = true;
                }
            }

            if (!rssi_valid)
                rssi = -55;

            infoResp->status = STATUS_COMPLETE;

            // rssi = hal_desc_get_rssi((struct rx_vector_1 *)&rwnx_hw->stats.last_rx.recvec1a, NULL);
            sprintf(paramList->devList, "%d", rssi);
#endif
            DPRINT_INFO("rssi=%d\r\n", rssi);
        }
   }

// send_cfm:
   WFA_ENC_TLV(WFA_STA_GET_PARAMETER_TLV, sizeof(dutCmdResponse_t), (BYTE *)infoResp, respBuf);
   *respLen = WFA_TLV_HDR_LEN + sizeof(dutCmdResponse_t);

   DPRINT_OUT_FUNC();

   return ret;
}


