int wfaAPDeAuthSta(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
    caAPDeAuthSta_t *DeAuthSta = (caAPDeAuthSta_t *)caCmdBuf;
    dutCmdResponse_t *APDeAuthStaResp = &gGenericResp;

    DPRINT_IN_FUNC();

    CMD_EXEC("/valid/bin/hostapd_cli -i %s deauthenticate  %s ", DeAuthSta->intf, DeAuthSta->staadd);

    wSLEEP(5);

    APDeAuthStaResp->status = STATUS_COMPLETE;
    WFA_ENC_TLV(WFA_AP_DEAUTH_STA_TLV, 4, (BYTE *)APDeAuthStaResp, respBuf);
    *respLen = WFA_TLV_HDR_LEN + sizeof(dutCmdResponse_t);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

