int wfaAPGetMacAddress(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
    dutCmdResponse_t *getmacResp = &gGenericResp;
    caAp11n_t *getmacParams = (caAp11n_t *)caCmdBuf;
    char *str;
    FILE *tmpfd;
    char string[257];
    int wlan_tag_value=1;

    DPRINT_IN_FUNC();

    wlan_tag_value=getmacParams->wlan_tag;

    char bssid1_value[] = "aa:05:cc:dd:ee:ff";
    char bssid2_value[] = "aa:05:cc:dd:ee:fe";

    //BSSID
    if(PARAM_SETUP(platform_id) == 0)
    {

    }
    else if(PARAM_SETUP(platform_id) < 10){
        sprintf(bssid1_value, "aa:0%d:cc:dd:ee:ff", PARAM_SETUP(platform_id));
        sprintf(bssid2_value, "aa:0%d:cc:dd:ee:fe", PARAM_SETUP(platform_id));
    }
    else{
        sprintf(bssid1_value, "aa:%d:cc:dd:ee:ff", PARAM_SETUP(platform_id));
        sprintf(bssid2_value, "aa:%d:cc:dd:ee:fe", PARAM_SETUP(platform_id));
    }

    /*
     * run the script "getipconfig.sh" to find out the mac
     */
    tmpfd = fopen("/valid/tmp/ipconfig.txt", "r+");
    if(tmpfd == NULL)
    {
      getmacResp->status = STATUS_ERROR;
      WFA_ENC_TLV(WFA_AP_GET_MAC_ADDRESS_TLV, 4, (BYTE *)getmacResp, respBuf);
      *respLen = WFA_TLV_HDR_LEN + 4;

      DPRINT_ERR("Error: file open failed\r\n");
      return WFA_FAILURE;
    }

    for(;;)
    {
       if(fscanf(tmpfd, "%256s", string) == EOF)
       {
           getmacResp->status = STATUS_COMPLETE;
           if(wlan_tag_value==2){
                  strcpy(getmacResp->cmdru.mac, bssid2_value);
           }else{
                  strcpy(getmacResp->cmdru.mac, bssid1_value);
           }

          break;
       }

       if(strncmp(string, "mac", 5) == 0)
       {
          str = strtok(string, "=");
          str = strtok(NULL, "=");
          if(str != NULL)
          {
             strcpy(getmacResp->cmdru.mac, str);
             getmacResp->status = STATUS_COMPLETE;
             break;
          }
       }
    }

    DPRINT_INFO("MAC add = %s\r\n",getmacResp->cmdru.mac);

    WFA_ENC_TLV(WFA_AP_GET_MAC_ADDRESS_TLV, sizeof(dutCmdResponse_t), (BYTE *)getmacResp, respBuf);
    *respLen = WFA_TLV_HDR_LEN + sizeof(dutCmdResponse_t);

    fclose(tmpfd);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

 /* wfaAPCommit()
  * this function is to start AP using hostapd.
  * fist remove the bridge used by wlan interface
  * remove the driver
  * insert the driver with needed parameters
  * setup bridge
  * launch hostapd with HostAP.conf configuration file built earlier
  * verify that interface has correctly been upped
  */

int wfaAPConfigCommit(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
    dutCmdResponse_t *setCommitResp = &gGenericResp;
    caApCommit_t* confParams = (caApCommit_t*)caCmdBuf;
    char * str;
    char string[256];
    FILE *FP;
    int wlan_tag;
    wlan_tag=confParams->wlan_tag_flag;
    char *ifname;
    int dut_mode=1;//AP MODE
    DPRINT_IN_FUNC();

    if ((first_run != 0 ) || (PARAM_SETUP(bridge) == 0))
    {
        DPRINT_BOX("Network bridge setup..." );

        // Configure and mount network bridge - now takes into account wlan0 ip set
        CMD_EXEC("./bridge_setup.sh %d rmv", DUT_IP_IDX);
        wSLEEP(3);
    }
    else{ first_run+=1;}

    //#######################################################################################################################################
    //#############################################  LOAD RW DRIVER / START SUPPLICANT ######################################################
    //#######################################################################################################################################
    if (DUT_PLATFORM == CEVAV7)
        ifname = "wlp4s0";
    else
        ifname = "wlan0";

    if (RestartDUT(ifname,dut_mode) == WFA_FAILURE)
        return WFA_FAILURE;

    // Second interface
    if ((DUT_PLATFORM == CEVAV7) && (wlan_tag == 1))
    {
        CMD_EXEC("ifconfig wlp4s2 up");
        wSLEEP(2);
    }

    CMD_EXEC("pkill -9 hostapd");
    wSLEEP(2);

    //Prepare Hostapd
    CMD_EXEC("mv -f /valid/bin/rw_hostapd.conf /valid/tmp/hostapd_%d.conf ",iteration);
    wSLEEP(10);

    //Start Hostapd
    CMD_EXEC("hostapd -B /valid/tmp/hostapd_%d.conf -dd -t -K -f /tmp/hostapd_%d.txt ",iteration,iteration);

    //Prepare Bridge
    if (PARAM_SETUP(bridge) == 1)
    {
        // Network bridge setup only - now takes into account wlan0 ip set
        DPRINT_BOX("Network bridge setup..." );
        CMD_EXEC("./bridge_setup.sh %d set", DUT_IP_IDX);
        wSLEEP(3);
    }

    CMD_EXEC("ifconfig | grep -i %s > /valid/tmp/ResultConfig.txt ",confParams->NomIf);

    FP= fopen("/valid/tmp/ResultConfig.txt","r");
    if (FP == NULL)
        return WFA_FAILURE;

    if (!fgets(string, 256, FP))
    {
        fclose(FP);
        return WFA_FAILURE;
    }
    str = strtok(string, ".");
    DPRINT_WARNING("str =  %s\r\n",str);

    if(str == NULL || str[0] == '\0'){setCommitResp->status = STATUS_ERROR;}
    else{setCommitResp->status = STATUS_COMPLETE;}

    WFA_ENC_TLV(WFA_AP_CONFIG_COMMIT_TLV, 4, (BYTE *)setCommitResp, respBuf);
    *respLen = WFA_TLV_HDR_LEN + 4;
    fclose(FP);

    iteration ++;

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

int wfaAPSetRFeature(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{
    caApRFeat_t *rfeatap = (caApRFeat_t *)caCmdBuf;
    dutCmdResponse_t *caResp = &gGenericResp;

    DPRINT_IN_FUNC();

    DPRINT_INFO("CHSWITCHMODE--> Initiate \r\n");
    CMD_EXEC("hostapd_cli -i %s chan_switch 10 5745 center_freq1=5775 bandwidth=80 vht", rfeatap->intf);

    caResp->status = STATUS_COMPLETE;
    WFA_ENC_TLV(WFA_AP_SET_RFEATURE_TLV, 4, (BYTE *)caResp, respBuf);
    *respLen = WFA_TLV_HDR_LEN + 4;

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

#ifdef __CLI__
/*
 * wfaStaCliCommand():
 */
int wfaStaCliCommand(int len, BYTE *caCmdBuf, int *respLen, BYTE *respBuf)
{

   char cmdName[32];
   char *pcmdStr=NULL, *str;
   int  st;
   char CmdStr[WFA_CMD_STR_SZ];
   FILE *wfaCliFd;
   char wfaCliBuff[64];
   char retstr[256];
   int CmdReturnFlag;
   char tmp[256];
   FILE * sh_pipe;

   caStaCliCmdResp_t infoResp;

   DPRINT_IN_FUNC();

   printf("The command Received: %s",caCmdBuf);

   memcpy(cmdName, strtok_r((char *)caCmdBuf, ",", (char **)&pcmdStr), 32);

   sprintf(CmdStr, "%s",cmdName);

   for(;;)
   {
      str = strtok_r(NULL, ",", &pcmdStr);
      if(str == NULL || str[0] == '\0')
          break;
      else
      {
          sprintf(CmdStr, "%s /%s",CmdStr,str);
          str = strtok_r(NULL, ",", &pcmdStr);
          sprintf(CmdStr, "%s %s",CmdStr,str);
      }
   }

   CmdReturnFlag =0;
   // check the return process
   wfaCliFd=fopen("/etc/WfaEndpoint/wfa_cli.txt","r");
   if(wfaCliFd!= NULL)
   {
      while(fgets(wfaCliBuff, 64, wfaCliFd) != NULL)
      {
         //printf("\nLine read from CLI file : %s",wfaCliBuff);
         if(ferror(wfaCliFd))
            break;

         str=strtok(wfaCliBuff,"-");
         if(strcmp(str,cmdName) == 0)
         {
            str=strtok(NULL,",");
            if(strcmp(str,"TRUE") == 0)
               CmdReturnFlag =1;

            break;
         }
      }
      fclose(wfaCliFd);
   }


   //printf("\n Command Return Flag : %d",CmdReturnFlag);
   st = 1;
   memset(&retstr[0],'\0',255);
   memset(&tmp[0],'\0',255);

   CMD_EXEC("%s",  CmdStr);
   printf("\nCLI Command -- %s\n", gCmdStr);

   sh_pipe = popen(gCmdStr,"r");

   if(!sh_pipe)
   {
      printf ("Error in opening pipe");
   }


   //tmp_val=getdelim(&retstr,255,"\n",sh_pipe);
   if (fgets(&retstr[0], 255, sh_pipe) == NULL)
   {
      printf("Getting NULL string\n");
   }

   if(pclose(sh_pipe) != 0)
   {
      printf("Error in closing shell cmd pipe");
   }
   sleep(2);

   printf("CLI retun value- %s\n",retstr);

   memcpy(tmp, strtok_r((char *)retstr, "-", (char **)&pcmdStr), 2);
   printf("\ncli status - %s",tmp);
   if(strlen(tmp) > 0)
   st = atoi(tmp);

   infoResp.resFlag=CmdReturnFlag;

   switch(st)
   {
       case 0:
       infoResp.status = STATUS_COMPLETE;
       if (CmdReturnFlag)
       {
           str=strtok_r(NULL, "\n", (char **)&pcmdStr);
           strncpy(tmp,str, 255);
           printf("\nresult - %s",tmp);
           if(tmp != NULL)
           {
                memset(&infoResp.result[0],'\0',WFA_CLI_CMD_LEN-1);
                strncpy(&infoResp.result[0], tmp,(strlen(tmp) < WFA_CLI_CMD_RESP_LEN ) ? strlen(tmp) : (WFA_CLI_CMD_RESP_LEN-1) );
                printf("Return CLI result to CA: %s****\n", &infoResp.result[0]);
           }
           else
                strcpy(&infoResp.result[0], "ENV_VAR_NOT_DEFINED");
       }
       break;
       case 1:
       infoResp.status = STATUS_ERROR;
       break;
       case 2:
       infoResp.status = STATUS_INVALID;
       break;
   }

   WFA_ENC_TLV(WFA_STA_CLI_CMD_RESP_TLV, sizeof(infoResp), (BYTE *)&infoResp, respBuf);
   *respLen = WFA_TLV_HDR_LEN + sizeof(infoResp);

   DPRINT_OUT_FUNC();

   return WFA_SUCCESS;
}
#endif //__CLI__



